           cleanAfter = false;
           if ~solver.setupDone
               solver.setupSolver(A, b);
               cleanAfter = true;
           end
           % Solve the linear system to a given tolerance
           if solver.reuseSetup
               code = 2 + double(solver.singleApply);
           else
               assert(~solver.singleApply, 'Cannot use singleApply without reuseSetup.');
               code = [];
           end

