                    eqs{mix} = insertCoupling(prop, mdl, eqs{mix}, mnames, names{mix}, q);
                else
                    mix = find(strcmpi(modelNames, cpl.model));
                    for m = mix
                        % Find equation indices
                        n = names{m};
                        n(cellfun(@iscell, n)) = '';

