classdef PerforationPressureGradient < StateFunction
    % Calculate the pressure difference between the reservoir cells and the
    % well-bore pressure (assuming pre-computed static connection
    % pressure-drop in wellSol.cdp)
    properties

    end

    methods
        function gp = PerforationPressureGradient(varargin)
            gp@StateFunction(varargin{:});
            gp = gp.dependsOn('FacilityWellMapping');
            gp = gp.dependsOn('pressure', 'state');
            gp = gp.dependsOn('bhp', 'state');
            gp.label = 'p_c-p_{bh}-g \Delta z \rho_{w}';
        end
        function dp = evaluateOnDomain(prop, model, state)
            map = prop.getEvaluatedDependencies(state, 'FacilityWellMapping');
            wellSol = state.wellSol;
            p = model.ReservoirModel.getProps(state, 'pressure');

            % Temporary
            isbhp = strcmpi(state.FacilityState.names, 'bhp');
            if any(isbhp)
                bhp = state.FacilityState.primaryVariables{isbhp}(map.perf2well);
            else
                bhp = vertcat(wellSol(map.active).bhp);
                bhp = bhp(map.perf2well);
            end
            cp = bhp + vertcat(wellSol(map.active).cdp);
            dp = p(map.cells) - cp;
            allowXFlow = cellfun(@(x) x.allowCrossflow, model.WellModels(map.active));
            if ~all(allowXFlow)
                % We have cross-flow, potentially
                vdp = value(dp);
                sgn = vertcat(map.W.sign);
                perfAllowXFlow = allowXFlow(map.perf2well);
                psgn = sgn(map.perf2well);
                % Set pressure drop to zero to cut of cross-flowing
                % connections. Note that sign == 0 is ambigious here.
                keep = perfAllowXFlow | (psgn == 1 & vdp <= 0) | (psgn == -1 & vdp >= 0);
                if isa(dp, 'ADI')
                    dp.val(~keep) = 0;
                else
                    dp(~keep) = 0;

classdef WellComponentPhaseFlux < StateFunction
    % Component flux in each phase for wells
    properties

    end

    methods
        function gp = WellComponentPhaseFlux(varargin)
            gp@StateFunction(varargin{:});
            gp = gp.dependsOn({'FacilityWellMapping', 'PhaseFlux', 'ComponentPhaseDensity'});
            gp = gp.dependsOn({'Density'}, 'PVTPropertyFunctions');
            gp.label = 'Q_{i,\alpha}';
        end
        function componentPhaseFlux = evaluateOnDomain(prop, facility, state)
            % Preliminaries
            model = facility.ReservoirModel;
            ncomp = model.getNumberOfComponents();
            nph = model.getNumberOfPhases();

            % Get fluxes and densities + well map needed
            [map, phaseFlux, componentDensity] = prop.getEvaluatedDependencies(state, 'FacilityWellMapping', 'PhaseFlux', 'ComponentPhaseDensity');
            wc = map.cells;
            W = map.W;
            nw = numel(W);
            componentPhaseFlux = cell(ncomp, nph);
            if nw == 0
                return;
            end
            nperf = numel(wc);

            perfTotalFlux = sum(value(phaseFlux), 2);

            wellIsInjector = map.isInjector;
            perfIsInjector = wellIsInjector(map.perf2well);

            % Compute flags for flow into well and cross-flow indicators.
            perfInjecting = perfTotalFlux > 0;            

            % If all perforations have cross-flow, we are dealing with a
            % switched injector. This routine is responsible for computing
            % component source terms for a given set of phase rates. We
            % assume that the sign of the well has switched since well
            % management is above this routine's paygrade.

classdef WellComponentTotalFlux < StateFunction
    % Component total flux for wells (with treatment for cross-flow)
    properties

    end

    methods
        function gp = WellComponentTotalFlux(varargin)
            gp@StateFunction(varargin{:});
            gp = gp.dependsOn({'FacilityWellMapping'});
            gp = gp.dependsOn('ComponentPhaseFlux');
            gp.label = 'Q_i';
        end

        function v = evaluateOnDomain(prop, model, state)
            ncomp = model.getNumberOfComponents();
            nph = model.getNumberOfPhases();
            v = cell(ncomp, 1);
            phase_flux = prop.getEvaluatedDependencies(state, 'ComponentPhaseFlux');

            for c = 1:ncomp
                % Loop over phases where the component may be present
                for ph = 1:nph
                    % Check if present
                    m = phase_flux{c, ph};
                    if ~isempty(m)
                        if isempty(v{c})
                            v{c} = m;
                        else
                            v{c} = v{c} + m;
                        end
                    end
                end
            end
            % If we have cross-flow and/or we are injecting more than one
            % component, we need to ensure that injecting perforation
            % composition mixtures equal the mix entering the wellbore
            map = prop.getEvaluatedDependencies(state, 'FacilityWellMapping');
            W   = map.W;
            vd  = value(v);
            vd  = horzcat(vd{:});
            vdt = sum(vd,2);

            isInjector = map.isInjector(map.perf2well);
            injection  = vdt > 0;

