classdef HystereticRelativePermeability < BaseRelativePermeability
    properties
        % hysteresisArgs = {};
        sg_min = [];
        sg_max = [];
        sg_tmax = [];
        nreg_imbibition = 1;
        minSat = 0.05;
    end

    methods
        function gp = HystereticRelativePermeability(model, varargin)
            gp@BaseRelativePermeability(model, varargin{:});
            nc = model.G.cells.num;
            if isempty(gp.regions)
                reg_defaulted = true;
                if isfield(model.rock, 'regions')
                    r = model.rock.regions;
                    if isfield(r, 'saturation')
                        gp.regions = r.saturation;
                        reg_defaulted = false;
                    end
                end
                if reg_defaulted
                    gp.regions = ones(nc, 1);
                end
            end
            gp = gp.dependsOn({'s', 'sMax'}, 'state');

            regi = repmat(2, nc, 1);
            if isfield(model.rock, 'regions')
                r = model.rock.regions;
                if isfield(r, 'imbibition')
                    regi = r.imbibition;
                end
            end
            regi  = unique(regi);
            nregi = numel(regi);
            reg = regi-nregi;
            f = model.fluid;
            % Maximum and minimum gas saturation
            if isfield(f, 'sWcon')
                sgmax = 1 - f.sWcon;
                if numel(sgmax) ~= nregi  % temporary
                    sgmax = ones(1, nregi)*sgmax;

classdef Mobility < StateFunction
    % Mobility for each phase. Normally rel. perm. divided by viscosity.
    properties (Access = protected)
        hasMultipliers = false;
    end

    methods
        function gp = Mobility(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'RelativePermeability'});
            gp = gp.dependsOn('Viscosity', 'PVTPropertyFunctions');
            gp.label = '\lambda_\alpha';
            gp.outputRange = [0, inf];
        end
        function mob = evaluateOnDomain(prop, model, state)
            kr = prop.getEvaluatedDependencies(state, 'RelativePermeability');
            mu = prop.getEvaluatedExternals(model, state, 'Viscosity');
            mob = cellfun(@(x, y) x./y, kr, mu, 'UniformOutput', false);
            if isfield(model.fluid, 'tranMultR')
                % Pressure dependent mobility multiplier 
                p = model.getProp(state, 'pressure');
                mult = model.fluid.tranMultR(p);
                mob = cellfun(@(x) x.*mult, mob, 'UniformOutput', false);
            end
            if prop.hasMultipliers
                mult = prop.getEvaluatedDependencies(state, 'MobilityMultipliers');
                for i = 1:numel(mult)
                    m = mult{i};
                    if ~isempty(m)
                        mu{i} = mu{i}.*m;
                    end
                end
            end
            % Check for negative values
            mv = cellfun(@(x) min(value(x)), mob);
            isAD = cellfun(@(x) isa(x, 'ADI'), mob);
            if any(isAD) && ~all(isAD)
                s = mob(isAD);
                s = s{1};
                bad = find(~isAD);
                for i = 1:numel(bad)
                    ix = bad(i);
                    mob{ix} = model.AutoDiffBackend.convertToAD(mob{ix}, s);
                end
            end

classdef NumericalPressureReductionFactors < StateFunction
    properties
        useDiagonalReduction
        includeDerivatives = true;
        checkDerivatives   = false;
        rowMajor           = false;
    end
    methods

        function prf = NumericalPressureReductionFactors(model, varargin)
            prf@StateFunction(model, varargin{:});
            AD = model.AutoDiffBackend;
            isDiag = isa(AD, 'DiagonalAutoDiffBackend');
            prf.useDiagonalReduction = isDiag && AD.useMex;
            if isDiag
                prf.rowMajor = AD.rowMajor;
            end
        end

        function weights = evaluateOnDomain(prop, model, state)
            % Get state with the full primary variable set as AD
            [stateAD, ncell, ncomp] = prop.getStateAD(model, state);
            % Timestep and mass at current and previous timestep
            dt    = state.reductionFactorProps.dt;
            % Pressure at current and previous iteration
            p      = value(state.pressure);
            mass  = model.getProps(stateAD, 'ComponentTotalMass');            
            factor = state.reductionFactorProps;
            factor.mass = mass;
            factor.pressure0 = factor.pressure;
            factor.pressure = value(p);
            % Weights at current and previous iteration
            w      = prop.getWeights(factor, dt, ncell, ncomp);
            w_prev = state.reductionFactorProps.weights;
            % Get derivatives of weights wrt pressure
            % Construct AD weights
            pAD = state.pressure;
            isAD = isa(pAD, 'ADI');
            if isAD && prop.includeDerivatives
                dwdp = prop.getWeightDerivatives(w, w_prev, factor);
                hasWeights = ~isempty(dwdp);
            else
                hasWeights = false;
            end
            weights = cell(ncomp, 1);

classdef PhasePressures < StateFunction
    % Pressure for each phase. Will always return one value for each phase,
    % even if all phases have the same pressure.
    properties
        has_pc
    end

    methods
        function gp = PhasePressures(model, varargin)
            gp@StateFunction(model, varargin{:});
            f = model.fluid;
            gp.has_pc = (model.water && model.oil && isfield(f, 'pcOW')) || ...
                        (model.gas   && model.oil && isfield(f, 'pcOG')) || ...
                        (~model.oil  &&              isfield(f, 'pcWG'));
            if gp.has_pc
                gp = gp.dependsOn({'CapillaryPressure'}, 'FlowPropertyFunctions'); 
            end
            gp = gp.dependsOn({'pressure'}, 'state');                   
            gp.label = 'p_\alpha';
        end

        function p_phase = evaluateOnDomain(prop, model, state)
            p = model.getProps(state, 'Pressure');
            nph = model.getNumberOfPhases();
            p_phase = cell(1, nph);
            [p_phase{:}] = deal(p);
            if prop.has_pc
                pc = prop.getEvaluatedExternals(model, state, 'CapillaryPressure');
                for i = 1:nph
                    if iscell(pc)
                        if ~isempty(pc{i})
                            p_phase{i} = p_phase{i} + pc{i};
                        end
                    else
                        p_phase{i} = p_phase{i} + pc(:, i);
                    end
                end
            end
        end
    end
end

