classdef SaturationProperty
    % Virtual class for utilities related to saturation function endpoint
    % scaling
    properties
        scalingActive = false;
        swcon = [];
        scalers
    end

    properties (Access = protected)
        cell_subset = ':';
    end

    methods
        function prop = storeConnateWater(prop, model, varargin)
            prop.swcon = prop.getConnateWater(model, varargin{:});
        end

        function prop = storeScalers(prop, model, varargin)
            % Store scalers in state function for faster evaluation
            r = model.rock;
            if isfield(r, 'krscale')
                tmp = struct();
                for type = reshape(fieldnames(r.krscale), 1, [])
                    t = type{1};
                    fn = fieldnames(r.krscale.(t));
                    fn_f = fieldnames(model.fluid.krPts);
                    fn = intersect(fn, fn_f);
                    s = struct();
                    for i = 1:numel(fn)
                        f = fn{i};
                        s.(f) = prop.getScalers(model, f, ':', t);
                    end
                    tmp.(t) = s;
                end
                prop.scalers = tmp;
            end
        end

        function swcon = getConnateWater(prop, model, state)
            % Get the connate water in each cell of the domain. This may
            % come from either the fluid or the rock, depending if the
            % scaling is active.
            if ~isempty(prop.swcon)
                swcon = prop.swcon;

classdef Viscosity < StateFunction

    methods
        function mu = Viscosity(model, varargin)
            mu@StateFunction(model, varargin{:});
            mu = mu.dependsOn('PhasePressures');
            mu.label = '\mu_\alpha';
            mu.outputRange = [0, inf];
        end

        function mu = evaluateOnDomain(prop, model, state)
            names = model.getPhaseNames();
            nph = numel(names);
            mu = cell(1, nph);
            p_phase = prop.getEvaluatedDependencies(state, 'PhasePressures');
            if ~iscell(p_phase)
                p_phase = {p_phase};
            end
            [sample, isAD] = getSampleAD(p_phase{:});
            for ph = 1:nph
                mu{ph} = prop.evaluatePhaseViscosity(model, state, names(ph), p_phase{ph});
            end
            if isAD
                for i = 1:numel(mu)
                    if ~isa(mu{i}, 'ADI')
                        mu{i} = model.AutoDiffBackend.convertToAD(mu{i}, sample);
                    end
                end
            end
        end

        function mu = evaluatePhaseViscosity(prop, model, state, name, p) %#ok
            mu = prop.evaluateFluid(model, ['mu', name], p);
        end

    end
end

