function [bO, muO] = getFunctions(PVCDO, reg)
    [bO, muO] = deal(cell(1, reg.pvt));

    for i = 1:reg.pvt
        pvcdo = PVCDO(i, :);

        por  = pvcdo(1); % ref pres
        bor  = pvcdo(2); % ref fvf
        co   = pvcdo(3); % compress
        muor = pvcdo(4); % ref visc
        vbo  = pvcdo(5); % viscosibility

        bO{i}  = @(po) exp(co.*(po-por))./bor;
        muO{i} = @(po) muor.*exp(vbo.*(po-por));
    end
end


