d  = (sg+sw-opt.swcr);
ww = (sw-opt.swcr)./d;


swm = (sw-opt.swcr)./(opt.swu-opt.sowcr-opt.swcr);
krW = f.krW(swm, varargin{:});

wg = (1-ww);

sg_m =@(sg) (sg-opt.sgcr)./(opt.sgu-opt.sogcr-opt.sgcr);
%sgm=(sg-opt.sgcr)./(opt.sgu-opt.sogcr-opt.sgcr);
sgm = sg_m(sg);
krG = f.krG(sgm, varargin{:});

function f = assignROCK(f, rock, reg)
    ntpvt = reg.pvt;
    cR   = rock(:, 2)';
    pRef = rock(:, 1)';
    if ntpvt == 1
        f.pvMultR = getFunction(cR, pRef, reg);
    else
        f.pvMultR = cell(1, ntpvt);
        for i = 1:ntpvt
            f.pvMultR{i} = getFunction(cR(i), pRef(i), reg);
        end
    end
end

function f = getFunction(cR, pRef, reg)
    ps = reg.prange;
    if isempty(ps)
        f = @(p) pvMult(p, cR, pRef);
    else
        fs = pvMult(ps, cR, pRef);
        f = @(p) reg.interp1d_uniform(ps, fs, p);
    end
end

function v = pvMult(p, cR, pRef)
    x = cR.*(p-pRef);
    v = 1 + x + 0.5*(x.^2);
end

