classdef CompositionalMixture
    properties
        Tcrit % Critical temperature in Kelvin
        Pcrit % Critical pressure in Pascal
        Vcrit % Critical volume in m^3 / mol
        acentricFactors % Acentric factors (dimensionless)
        molarMass % Component mass (kg / mol)
        names % Names of each component. Each name must be unique.
        name % Name of the fluid mixture itself
    end

    properties ( Access = protected)
        bic % Binary interaction coefficients
    end

    methods
        function fluid = CompositionalMixture(names, Tcrit, Pcrit, Vcrit, acentricFactors, molarMass, varargin)
            if nargin == 0
                disp('Empty fluid - no validation');
                return
            end

            for i = 1:numel(names)
                cts = sum(strcmp(names{i}, names));
                if cts > 1
                    warning(['Component ', num2str(i), ': ', names{i}, ' occurs multiple times.']);
                end
            end
            fluid.names = names;
            fluid.Tcrit = Tcrit;
            fluid.Pcrit = Pcrit;
            fluid.Vcrit = Vcrit;
            fluid.acentricFactors = acentricFactors;
            fluid.molarMass = molarMass;
            ncomp = numel(fluid.names);

            fluid.bic = zeros(ncomp, ncomp);
        end

        function n = getNumberOfComponents(fluid)
            n = numel(fluid.names);
        end

        function bic = getBinaryInteraction(fluid)
            bic = fluid.bic;

classdef CompositionalPropertyModel < PropertyModel
    % Property model for compositional models
    properties
        volumeShift
    end

    methods
        function model = CompositionalPropertyModel(varargin)
            model = model@PropertyModel(varargin{:});
        end
        function rho = computeDensity(model, EOS, p, x, Z, T, isLiquid)
            % Predict mass density from EOS Z-factor
            ncomp = numel(model.fluid.names);
            M = 0;
            if iscell(x)
                for i = 1:ncomp
                    M = M + x{i}.*model.fluid.molarMass(i);
                end
            else
                M = sum(bsxfun(@times, x, model.fluid.molarMass), 2);
            end
            rho = model.computeMolarDensity(EOS, p, x, Z, T, isLiquid);
            rho = rho.*M;
        end

        function rho = computeMolarDensity(model, EOS, p, x, Z, T, isLiquid)
            % Predict molar density from EOS Z-factor
            R = 8.3144598;
            V = (R.*T.*Z)./p;
            if ~isempty(model.volumeShift)
                shift = reshape(model.volumeShift, 1, []);
                Tc = model.fluid.Tcrit;
                Pc = model.fluid.Pcrit;

                beta = EOS.omegaB.*R.*Tc./Pc;
                factors = shift.*beta;
                if iscell(x)
                    corr = 0;
                    for i = 1:numel(x)
                        corr = corr + factors(i).*x{i};
                    end
                else
                    corr = sum(bsxfun(@times, factors, x), 2);
                end
                V = V - corr;

