            model = model@ThreePhaseBlackOilModel(G, rock, fluid, varargin{:});

            % Use CNV style convergence 
            model.useCNVConvergence      = true;
            model.hystereticResSat       = false;
            model.dynamicEndPointScaling = false;

            % All phases are present
            model.water   = true;
            model.oil     = true;
            model.gas     = true;
