muw = 0.30860;  rhow = 975.86; sw    = 0.1;
muc = 0.056641; rhoc = 686.54; srco2 = 0.2;
kwm = [0.2142 0.85];

%% VE-incomp: C-accelerated simulation of sloping aquifer
% The incompressible VE solvers also have an accelerated back-end solver
% written in C. This example demonstrates this solver for a synthetic model
% of a sloping aquifer. The topography of the top surface and the
% geological layers in the model are generated by combining the membrane
% function (MATLAB logo) and a sinusoidal surface with random
% perturbations.
%
% CO2 is injected in the aquifer for a period of 30 years. Thereafter we
% simulate the migration of the CO2 in a post-injection period of 720
% years.

