function mu = viscCO2F1998(T, rho)
% SYNOPSIS:
% mu = viscCO2F1998(T, rho)
%
% DESCRIPTION:
% Calculate CO2 viscosity from Vesovic et al., J Phys Chem Ref Data (1990) 
% and Fenghour et al., J Phys Chem Ref Data (1998), as described in
% Hassanzadeh et al., IJGGC (2008). 
%
% RANGE:
%
% INPUT:
% T:    Double with temperature value in Kelvin
% rho:  Double with density value in kg/m^3
%
% OUTPUT: 
% mu:   Double with dynamic viscosity in Pa*s
%

% Check if T, P conditions are within range

% From Hassanzadeh et al., IJGGC (2008)
% Constants
e = [0.235156, -0.491266, 5.211155*10^-2, ...
     5.347906*1e-2, -1.537102*1e-2];
f = [5.5934*1e-3, 6.1757*1e-5, 0.0, 2.6430*1e-11];
g = [0.4071119*1e-2, 0.7198037*1e-4, 0.2411697*1e-16, ...
     0.2971072*1e-22, -0.1627888*1e-22];
exps = [0 1 2 3 4];

% Functions of scaled T
T_x    = T*(1/251.196);
psi_m  = exp(sum(e.*log(T_x).^exps));

% Compute viscosity
a1 = 1.00697*T^0.5/psi_m;
a2 = g(1)*rho;
a3 = g(2)*rho^2;
a4 = g(3)*rho^6/T_x^3;
a5 = g(4)*rho^8;
a6 = g(5)*rho^8/T_x;
if T < 313.15
    a7 = sum(f.*rho);
else
    a7 = 0;

%% Johansen formation: the effect of coarsening on trapping
% When working with subsea reservoirs coarsening will always be a factor:
%
% * Simulations on very large grids become prohibitively expensive in terms
% of computing power very fast.
% * All grids are essentially coarse approximations of highly complex
% geometry. Different grids have a different scale for each cell depending
% on what kind of data was used to produce the grid in the first place and
% the intended usage of the datasets.
%
% This example demonstrates the effects of geometry coarsening on a model
% from the CO2 Storage Atlas grids, with a special focus on structural
% trapping. To this end, we generate six realizations of the Johansen
% formation: The first is the full dataset, the second coarsened by a
% factor 2 in both i and j directions, the third a factor 3, and so on.
% This gives a set of grids where the finest has approximately 80,000
% cells, while the most coarse has ~2,000 cells. In the finest grid, each
% cell has a resolution of 500x500 m^2 per cell, while the coarsest has
% 3000x3000 m^2. The resolution in both grids is fairly large in compared
% with typical simulation grids in petroleum application.

mrstModule add co2lab-common co2lab-spillpoint coarsegrid deckformat

N = 6;
[Grids, res] = deal(cell(numel(N),1));
for i = 1:N
    fprintf(1,'\nLoading Johansen formation (coarsening factor: %d)...\n', i);
    gr = getAtlasGrid('Johansenfm', 'coarsening', i);
    G = processGRDECL(gr{1});
    % Create top surface grid
    Gt = topSurfaceGrid(computeGeometry(G(1)));
    Grids{i} = Gt;
    % Create trapping and store volumes of each trap
    res{i} = trapAnalysis(Gt, true);
    res{i}.volumes = volumesOfTraps(Gt, res{i}, []);
end

%% Plot a subset of the formation with different degree of coarsening
% We first define a subdomain consisting of a minimum and maximum value for
% both x and y coordinates which is then plotted on the fine grid.
G = Grids{1};

subdomain = [5.25e5, 6.70e6; 5.30e5, 6.75e6];

x = G.cells.centroids(:,1);

%% Trapping example
% In this example, we demonstrate the basic routines for computing traps,
% accumulation areas, spill paths, etc. To this end, we will use a simple
% shoe-box with a dip and a perturbed top surface.

mrstModule add co2lab-spillpoint co2lab-common co2lab-legacy co2lab-demo coarsegrid
%% Make grid and rock data
% We consider a sandbox of dimensions 10 km x 5 km x 50 m, that lies at a
% depth of 1000 m and has an inclination in the x-direction. For the top
% surface, we add a smooth sin/cos perturbation that will create domes. The
% porosity is set uniformly to 0.25
[Lx,Ly,H] = deal(10000, 5000, 50);
G  = cartGrid([100 100 1],[Lx Ly H]);
x  = G.nodes.coords(1:G.nodes.num/2,1)/Lx; 
y  = G.nodes.coords(1:G.nodes.num/2,2)/Ly;
z  = G.nodes.coords(1:G.nodes.num/2,3)/H;
zt = z + x - 0.2*sin(5*pi*x).*sin(5*pi*y.^1.5) - 0.075*sin(1.25*pi*y) + 0.15*sin(x+y);
zb = 1 + x;
G.nodes.coords(:,3) = [zt; zb]*H+1000;
G = computeGeometry(G);

%% Construct top surface grid
% We create a hybrid grid that represents the top surface. The grid is a 2D
% grid defined as a surface in 3D and contains a mapping from the 2D cells
% on the surfrace to the column of volumetric cells that lie below in the
% 3D grid. For visualization purposes, we create an extra grid that lies
% above the true top surface.
Gt = topSurfaceGrid(G);

figure;
Gt_zshifted = Gt; 
Gt_zshifted.nodes.z = Gt_zshifted.nodes.z - 15;
plot_opts = {'edgeColor', 'k', 'edgeAlpha', 0.1};
plotGrid(G, plot_opts{:});
