%% Examples to demonstrate forecast of CO2 leakage and its application
% By assuming a system's flow dynamics are gravity-dominated, we determine
% the amount of CO2 remaining in the domain using spill-point dynamics.

mrstModule add co2lab-common co2lab-ve co2lab-spillpoint co2lab-legacy

%% 1. Synthetic grid
% For simplicity, we first consider a synthetic grid of a sloping and
% perturbed topsurface. Beginning with a domain that is fully saturated
% with CO2, the forecast amount of CO2 remaining is shown to be equivalent
% to the structural trapping capacity (in the event that there is no
% residual trapping). On the other hand, when residual trapping is
% included, the forecast amount remaining is a conservative estimate (since
% we do not forecast the areal sweep of the plume as it migrates), but this
% estimate is shown to be close to the structural and residual trapping
% capacity.

% Getting grid and rock:
Gt = dippedPerturbedGrid();
rock2D.poro = ones(Gt.cells.num,1) * 0.25;
rock2D.perm = ones(Gt.cells.num,1) * 500 * milli*darcy;

%%
% Trap analysis: labeling trap and catchment numbers
figure; hold on
ta = trapAnalysis(Gt, true);
plotGrid(Gt, 'facecolor','none', 'edgealpha',0.1);
colorizeCatchmentRegions(Gt, ta);
num_traps = numel((unique(ta.traps(ta.traps ~= 0))));
for i = 1:num_traps
    trapcells = find(ta.traps==i);
    plotCellData(Gt, ones(Gt.cells.num,1).*i, trapcells, ...
        'facecolor',[0.5 0.5 0.5], 'facealpha',0.5, 'edgecolor','none');
end
top = topCellOfTrap(Gt, ta);
[x, y] = deal(Gt.cells.centroids(top,1), Gt.cells.centroids(top,2));
data = 1:1:numel(top);
data = data';
text(x, y, Gt.cells.z(top)-3, cellstr(num2str(data, '%3.0f')), ...
   'HorizontalAlignment','center', 'FontSize',16, 'FontWeight', 'bold');
axis tight off; view([42,48])

%%
% Fluid model
seainfo = getSeaInfo('NorthSea',760);

mrstModule add co2lab-common co2lab-ve
mrstModule add static-modeling
mrstModule add ad-core ad-props ad-blackoil
mrstModule add mrst-gui
gravity on;

% In this example, we compare the result of a full 3D simulation and its
% corresponding VE simulation on a cross section of a sloping aquifer.  
% The simulation can be run with or without the following effects:
% - Residual trapping
% - Heterogeneous rock properties
% - Impact of small-scale oscillations in caprock ('rugosity')
% 
% Note that if you include sub-scale oscillations in caprock, the grid used 
% in the 3D simulation will have to be much finer in order to properly capture
% the geometry.  The VE model will still use the original resolution grid, as
% caprock rugosity is modeled as an upscaled effect anyway.
%
% You may turn on and off these effects in the 'User options' section below.

%% User options
heterogeneity = true;
residual = true;
rugosity = false;

show_plots = true;

%% Set up 3D test grid

[xres, zres] = deal(100, 25); 
[L, H] = deal(5000 * meter, 25 * meter);

% The call to 'make_testgrid' sets up a grid with the specified dimension,
% resolution and slope, and with a large structural trap towards the right side.
G = make_testgrid([xres, 1, zres], [L, 1, H], 5, 0.02, 2000, [0.6, 900, 30]);

[xfac, GFine] = deal(1, []);
if rugosity
    % we need a high-resolution grid to capture the high-frequency caprock oscillations
    xfac = 12;
    GFine = make_testgrid([xres*xfac, 1, zres], [L, 1, H], 5, 0.02, 2000, [0.6, 900, 30], ...
                          'ripples_amplitude_x', H/30, 'ripples_number_x', 200);
end

%% Load modules, turn on gravity and set utility functions
mrstModule add co2lab-common co2lab-ve ad-core ad-props ad-blackoil
gravity on;

view_side = @() view(0,0);
view_oblique = @() view(-13, 2);

%%
% In this example, we compare VE and 3D simulations of injected CO2 migrating up
% a (synthetic) sloping aquifer, while looking at the effect of residual
% trapping and capillary effects.


%% Residual trapping, sharp interface
% In the first example, we include residual trapping but no capillary
% pressure in the simulation.  The result is a sharp-interface between CO2
% and water, and a trail of trapped CO2 in the wake of the moving plume.

srw = 0.25; % residual water satuation
srg = 0.25; % residual gas saturation

% Simulate cross-sections
[G, states_res, G_VE, states_VE_res, sat_VE_converted_3D_res, timing_res, wellcell] = ...
    sloping_aquifer('cross_sectional', true, 'zres', 40, 'srw', srw, 'srg', srg);

% plot grid with well cell
fig = figure;
plotGrid(G, 'facecolor', 'yellow', 'facealpha', 0.6, 'edgealpha', 0.3);
plotGrid(G, wellcell, 'facecolor', 'red');
set_fig_standardformat(fig, "Cross-sectional simulation grid, with cell containing injection point");
view_side()

% Compare 3D and reconstructed VE plots
fig = figure;
subplot(2,1,1); plotCellData(G, states_res{20}.s(:,2), 'edgealpha', 0.1); view_side(); 
subplot(2,1,2); plotCellData(G, sat_VE_converted_3D_res{20}, 'edgealpha', 0.1); view_side();
set_fig_standardformat(fig, {'CO2 saturation, timestep 20, 3D', ...
                       'CO2 saturation, timestep 20, VE'});

fig = figure;
subplot(2,1,1); plotCellData(G, states_res{end}.s(:,2), 'edgealpha', 0.1); view_side(); 
subplot(2,1,2); plotCellData(G, sat_VE_converted_3D_res{end}, 'edgealpha', 0.1); view_side();
set_fig_standardformat(fig, {'CO2 saturation, last timestep, 3D', ...
                       'CO2 saturation, last timestep, VE'});

%% Load modules, turn on gravity and set utility functions
mrstModule add co2lab-common co2lab-ve ad-core ad-props ad-blackoil
gravity on;

view_side = @() view(0,0);
view_oblique = @() view(-13, 2);

%% Compare VE solution with 3D solutions with increasing vertical resolution

% In this example, we demonstrate how the solution from the 3D model
% converges towards the VE solution when vertical grid resolution is
% increased.  Although the result is the same, the VE simulation runs at a
% fraction of the time used to simulate the 3D model.  We simulate on a 
% section of a synthetic, sloping aquifer model.

%% Compare cross-sections, with low vertical resolution (5)
[G5, states5, G5_VE, states5_VE, sat5_VE_converted_3D, timing5, wellcell5] = ...
    sloping_aquifer('cross_sectional', true, 'zres', 5);

% plot grid
fig = figure;
plotGrid(G5, 'edgealpha', 0.3);
set_fig_standardformat(fig, 'Cross-sectional simulation grid'); view_side(); 

% plot grid with well cell
fig = figure;
plotGrid(G5, 'facecolor', 'yellow', 'facealpha', 0.6, 'edgealpha', 1);
plotGrid(G5, wellcell5, 'facecolor', 'red');
set_fig_standardformat(fig, "Cross-sectional simulation grid, with cell containing injection point");
view_side()

% Compare 3D and reconstructed VE plots
fig = figure;
subplot(2,1,1); plotCellData(G5, states5{end}.s(:,2)); view_side(); 
subplot(2,1,2); plotCellData(G5, sat5_VE_converted_3D{end}); view_side();
set_fig_standardformat(fig, {'CO2 saturation, last timestep, 3D', ...
                       'CO2 saturation, last timestep, VE'});

%% compare cross-sections, using higher vertical resolution (15)
[G15, states15, G15_VE, states15_VE, sat15_VE_converted_3D, timing15, wellcell15] = ...
    sloping_aquifer('cross_sectional', true, 'zres', 15);

% Compare 3D and reconstructed VE plots
fig = figure;
subplot(2,1,1); plotCellData(G15, states15{end}.s(:,2), 'edgealpha', 0.2); view_side();

