function [edges, m, s] = swap(k, edges, m, s)
% Do one edge swap.  With N=size(edges,1), N-1 edge swaps will sort edges.


   % Find next edge
   i = k+find(any(edges(k+1:end,:)==k, 2));


   if any(i),
      i = i(1);

      % Swap rows i and k
      a=edges(k,:); edges(k,:)=edges(i,:); edges(i,:)=a;
      a=m(k);       m(k)=m(i);             m(i)=a;
      a=s(k);       s(k)=s(i);             s(i)=a;
   end

