MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
GNU General Public License for more details.

You should have received a copy of the GNU General Public License
along with MRST.  If not, see <http://www.gnu.org/licenses/>.
%}
datafolder = fullfile(getDatasetPath('sleipner2019'),...
    'feeders','data');

filelist = dir(fullfile(datafolder,'*_feeder_*'));

% Layers that each feeder is present in according to 
% Sleipner 2019 Reference Model - Polygons_feeders_chimney.pptx
% Add layer 9 as there are 10 layers in our model including the thick shale
% layer.
layernos{1} = 1:1:9;
layernos{2} = 5;
layernos{3} = 7;

feeders = cell(length(filelist),1);

for k = 1 : length(filelist)
  fullFileName = fullfile(datafolder, filelist(k).name);
  dat = dlmread(fullFileName,'', 16,0);
  polynos = unique(dat(:,4));
  for j = 1:numel(polynos)
    inds = dat(:,4) == polynos(j);
    feeders{k}.outline{j}  = dat(inds,1:3);
  end

%% Simulate the SPE10 base case
% The simulation uses a mimetic pressure solver and an implicit transport
% solver.
mrstModule add incomp agmg

clear, close all hidden

%%
use_mimetic = false;
use_reorder = false;
spe10_data  = fullfile(fileparts(mfilename('fullpath')), ...
                       '..', 'spe10_rock.mat');
if ~exist(spe10_data, 'file')
   if ~make_spe10_data
      error(['Failed to establish on-disk representation of ', ...
             'SPE10 rock data']);
   end
end

%%
layers = 1 : 85;

cartDims = [60, 220, numel(layers)];
rock     = SPE10_rock(layers);

rock.perm = convertFrom(rock.perm, milli*darcy);

is_pos             = rock.poro > 0;
rock.poro(~is_pos) = min(rock.poro(is_pos));

physDims = cartDims .* [20, 10, 2]*ft;

G = computeGeometry(cartGrid(cartDims, physDims));

if use_mimetic
   try
      require mimetic
   catch
      mrstModule add mimetic
   end

   S = computeMimeticIP(G, rock);
else
   T = computeTrans(G, rock);
end

