along with MRST.  If not, see <http://www.gnu.org/licenses/>.
%}

    opt = struct('layers', 1:85, ...
                 'dt',      30*day, ...
                 'T',       2000*day, ...
                 'rampup',  8, ...
                 'I',       1:60, ...
                 'J',       1:220, ...
                 'make2D',  false, ...
                 'minporo', 0.01);
    opt = merge_options(opt, varargin{:});

    mrstModule add spe10 ad-props ad-blackoil ad-core

    srw = 0.2;
    sro = 0.2;
    pRef = 6000*psia;

    % Fluid relative permeabilities
    fluid.krW = coreyPhaseRelpermAD(2, srw, 1, srw + sro);
    fluid.krO = coreyPhaseRelpermAD(2, sro, 1, srw + sro);

    % Water props
    bW0 = 1./(1.01);
    fluid.bW = @(p, varargin) bW0*exp((p - pRef)*3e-6/psia);

%% Setup a simple layered model
mrstModule add wellpaths

rng(0);
[nx, ny, nz] = deal(50, 50, 15);
G = computeGeometry(processGRDECL(makeModel3([nx ny nz])));
% Prior to accurate intersecting algoritms, a more cost effective rough search 
% is performed based on grid face bounding boxes. To avoid overhead, add these 
% fields to the grid prior to calling 'computeTraversedCells'
G = addBoundingBoxFields(G);

[~, ~, K] = gridLogicalIndices(G);
poroLayers = .2 + .5*rand(nz,1);
poro       = poroLayers(K);
permX      = (100*milli*darcy)*poro.^3./(1-poro.^2);
rock       = makeRock(G, [permX, permX, .1*permX], poro);
figure, plotCellData(G, log(rock.perm(:,1))); view(3)

%% Define well trajectory and compute intersection with grid
pnts = [100 150 -15
        200 250 -1
        400 300  6
        700 600  10];

dp     = diff(pnts);
len    = [0; cumsum(sqrt(dot(dp, dp, 2)))];
% interpolate 100 points along splines passing trough pnts
traj   = interp1(len, pnts, (0:.01:1)*len(end), 'spline');

% Compute intersections between grid and trajectory. Returned struct
% contains cell indiices of traversed cells, vector representing part of 
% segment (exit point minus entry point) and a weight which which is typically 
% one except in cases where a segment is shared between multiple cells   
T = computeTraversedCells(G, traj)  %#ok

% plot trajectory, vertical intersection, and cells traversed by trajectory
figure, hold on
col = log(rock.perm(:,1));
poly = computeVerticalGridIntersection(G, traj);
patch('Faces', poly.nodes, 'Vertices', poly.coords3D, ...
      'FaceVertexCData', col(poly.cellIx), ...
      'FaceColor', 'flat', 'EdgeAlpha', .3, 'FaceAlpha', .2)
plot3(traj(:,1), traj(:,2), traj(:,3), '-b','LineWidth', 2);
plotCellData(G, col, T.cell, 'EdgeAlpha', .5, 'FaceAlpha', .5);
axis off, view([-1 2 2]), daspect([1 1 .1]), camproj perspective

%% Define a model
mrstModule add ad-core ad-blackoil diagnostics wellpaths
km = kilo*meter;
pdims = [5, 4, 0.01]'*km;

% dims = [50, 40, 10];
dims = [25, 20, 5];

G = cartGrid(dims, pdims);
G = computeGeometry(G);
%% Define a forked well
% We define four curves, with some common points to combine them into a
% single well path.

p1 = [0.25, 0.5, 0.9, 1.5]'*km;

n = numel(p1);

z = [.25, 0.5, 0.75, .80]'*pdims(3);

a = [p1(1)*ones(n, 1), p1];
b = [p1,               p1(1)*ones(n, 1)];
c = [p1,               p1];

origin = [0, 0, 0; a(1, :), z(1)];

% First foru well paths.
wellpath0 = makeSingleWellpath(origin);
wellpath1 = makeSingleWellpath([a, z]);
wellpath2 = makeSingleWellpath([b, z]);
wellpath3 = makeSingleWellpath([c, z]);
% Combine into single well path
wellpath_fork = combineWellPaths({wellpath0, wellpath1, wellpath2, wellpath3});

% Plotting
clf;
plotWellPath(wellpath_fork);
%% Make a comb-like well
x = [3, 3.5, 4, 4.5]'*km;
y = [3.5, 3, 2.5, 2]'*km;

y0 = [3.75*km; y];
x0 = x(end)*ones(numel(y)+1, 1);

dz = 1/numel(y);

function [W, trajectory] = addWellFromTrajectory(W, G, rock, traj, varargin)
% This function adds a well based on a piecewise linear trajectory traj.
% All function arguments are the same as for addWell except for in place of
% cellInx, there should be a nx3 matrix of trajectory coordinates.

%{
