%}
    fluid = model.fluid;
    s = model.operators;   
    dpO    = s.Grad(pO) - fluid.rhoOS .* gdz;    
    upco  = (value(dpO) <= 0);
    [krOf, krO] = s.splitFaceCellValue(s, upco, krO);    
