%
% SYNOPSIS:
%   model = CreateKr(model)
%
% PARAMETERS:
%   model - struct containing following fields:
%   - experiment: saturation functions used for forward modeling
%
% RETURNS:
%   model - adds the the following fields to the struct:
%   - satfun: struct with relative permeability information inside
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
kr_struct = model.experiment.satfun.kr;
switch string(kr_struct.type)
    case 'TABLE'
        [Sw, ia]  = unique(kr_struct.table.(1)); 
        kr_struct.table = kr_struct.table(ia,:);
        krw = kr_struct.table.(2); 
        kro = kr_struct.table.(3);    
        kr_struct.Swc    = min(Sw); 
        kr_struct.Sor    = 1 - max(Sw);
        kr_struct.krwSor = max(krw);
        kr_struct.kroSwc = max(kro); 
        model.experiment.satfun.kr = kr_struct;
        [Sw, krw, kro] = kr_correction(Sw, krw, kro);
    case 'MODIFIED-COREY'
        [Sw, krw, kro] = modified_corey_kr(kr_struct.Swc, kr_struct.Sor, ...
            kr_struct.krwSor, kr_struct.kroSwc, kr_struct.nW, kr_struct.nNW);
    case 'MODIFIED-COREY-MASALMEH'
        [Sw, krw, kro] = modified_corey_masalmeh_kr(kr_struct.Swc, kr_struct.Sor, ...
            kr_struct.krwSor, kr_struct.kroSwc, kr_struct.nW, kr_struct.nNW,...
            kr_struct.cW, kr_struct.cNW);

function procedure = CreateProcedure(table, processType)
%
% DESCRIPTION: creates procedure table from the schedule table
%              which is used to run the simulation
%
% SYNOPSIS:
%   procedure = CreateProcedure(table, processType)
%
% PARAMETERS:
%   table - schedule table read from a .txt file
%   processType - can be "SS", "USS" or "CENT"
%
% RETURNS:
%   procedure - table used in the Run.m module for simulation
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
if(strcmpi(processType,"SS") || strcmpi(processType,"USS"))
    headers = table.Properties.VariableNames;
    [headers,~] = SplitHeaders(headers);

    timeFrom  = table{1:end-1,1};
    timeTo    = table{2:end,1}; 
    totalRate = table{1:end-1,2};
    oilFrac   = table{1:end-1,3};
    watFrac   = table{1:end-1,4}; 
    oilRate   = table{1:end-1,2} .* table{1:end-1,3}; 
    watRate   = table{1:end-1,2} .* table{1:end-1,4};
    oilCum    = cumsum(oilRate .* (timeTo - timeFrom));
    watCum    = cumsum(watRate .* (timeTo - timeFrom)); 

    data = [timeFrom, timeTo, totalRate, oilFrac, watFrac, ...
                      oilRate, watRate, oilCum, watCum];

    % table headers
    oilRateHeader  = 'oil rate'; oilRateQuantity = 'rate';
    watRateHeader  = 'water rate'; watRateQuantity = 'rate';

function model = CreateRock(model)
%
% DESCRIPTION: adds porosity and pearmeability information to the model
%
% SYNOPSIS:
%   model = CreateRock(model)
%
% PARAMETERS:
%   model - struct containing following fields:
%   - experiment: saturation functions used for forward modeling
%   - simulation: time stepping and grid cells information
%   - grid: struct with the information about gridding
%
% RETURNS:
%   model - adds the the following fields to the struct:
%   - rock: struct with the porosity, permeability and satNum index
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
experiment = model.experiment;
simulation = model.simulation;
grid       = model.grid;
G          = grid.G;
poro = experiment.rock.poro.value * ones(G.cells.num, 1);
perm = experiment.rock.perm.value * ones(G.cells.num, 1);

rock = makeRock(G, perm, poro); 
rock.pv = poreVolume(G, rock); 
if (isfield(simulation,'bCells'))
    rock.regions = struct('saturation', grid.satNum);
end
model.rock = rock;

function model = Create_pc_history_match(x, model, params_no_kr)  
%
% DESCRIPTION: changes the capillary pressure in the model struct during
%              the history matching process
%
% SYNOPSIS:
%   model = Create_pc_history_match(x, model, params_no_kr)  
%
% PARAMETERS:
%   - x: parameter set for history matching iterations
%   - model: struct on which the history matching process is running
%   - params_no_kr: number of the parameters for the relative permeability
%
% RETURNS:
%   model - struct with the capillary pressure changed
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
x = x(:);
row_names = model.history_match.RowNames;
if model.history_match.pc.status
    if strcmp(model.history_match.pc.type,'BROOKS-COREY')
        p_s = brooks_corey_pc_handle(model, x, row_names);
        [sw_pc, pc_array] = brooks_corey_pc(p_s.swc_pc, p_s.sor_pc, p_s.pd, p_s.lambda_pc);
    elseif strcmp(model.history_match.pc.type,'VAN-GENUCHTEN')
        p_s = van_genuchten_handle(model, x, row_names);
        [sw_pc, pc_array] = van_genuchten(p_s.swc_pc, p_s.sor_pc, p_s.alpha, p_s.n_pc);
    elseif strcmp(model.history_match.pc.type,'POINT-BY-POINT')
        if model.history_match.kr.status && strcmp(model.history_match.kr.type,'POINT-BY-POINT')
            sw_pc = sort(model.history_match.pc.Sw_hm);
            sw_pc = sw_pc(:);
            Sw_kr_hm = sort(model.history_match.kr.Sw_hm);
            Sw_kr_hm = Sw_kr_hm(:); len_sw_kr = numel(Sw_kr_hm);
            pc_array = sort((x(len_sw_kr*2-1:len_sw_kr*2+length(sw_pc)-2) .* Convert('bar')),'descend');
        else
            sw_pc = sort(model.history_match.pc.Sw_hm);
            sw_pc = sw_pc(:);

function model = save_for_HM (model, state0)
%
% DESCRIPTION: Save the required parameters, used during the history
%              matching
%
% SYNOPSIS:
%   model = save_for_HM (model, state0)
%
% PARAMETERS:
%   model - struct containing the following fields:
%   - dynamic: information saved during the simulation
%   - experiment: saturation functions used for forward modeling
%   - grid
%   state0 - initial state of the simulation
%
% RETURNS:
%   model - struct containing the following fields:
%   - history_match: parameters used in gradient based and MCMC
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
model.history_match.calculatedp = [];
params = model.dynamic.params;
G = model.grid.G; n_cells = G.cells.num;
model.history_match.endofsched_t = model.experiment.schedule.procedure{:,2};
sample_L = model.experiment.geometry.length.value;
states = model.dynamic.states;
centroids = G.cells.centroids;

if (isfield(model.simulation,'bCells'))
    sw_profile = zeros(length(params.cumScheduleSteps) + 1, n_cells + 1);
    sw_profile(2:end,1) = params.cumScheduleSteps;
    sw_profile(1,2:end) = [0;centroids(2:end-1,1) - 2*centroids(1,1);sample_L];
    sw_profile(2,2) = interp1(centroids(2:3,1),state0.s(2:3,1),0,'linear','extrap');
    sw_profile(2,end) = interp1(centroids(end-2:end-1,1) - ...
        2 * centroids(1,1),state0.s(end-2:end-1,1),sample_L,'linear','extrap');
    sw_profile(2,3:end-1) = state0.s(2:end-1,1)';

