function model_flooding = historymatch_multi_obj(model_flooding)
%
% DESCRIPTION: main history match function for the multi objective history
%              matching using genetic algorithm
%
% SYNOPSIS:
%   model_flooding = historymatch_multi_obj(model_flooding)
%
% PARAMETERS:
%   model_flooding - struct containing following fields:
%   - history_match - including history matching boundaries and initial
%   points (in case of a simultaneous history matching, relavant info
%   should be included as well)
%   - experiment - heterogeneity can be included here
%
% RETURNS:
%   model_flooding - struct containing following fields:
%   - history_match - includes the history matching results
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
lb = model_flooding.history_match.lb;
ub = model_flooding.history_match.ub;
x0 = model_flooding.history_match.x0;
UseParallel = model_flooding.history_match.UseParallel;
algorithm = model_flooding.history_match.algorithm;

%setup centrifuge model
obj_fun_type = model_flooding.history_match.obj_fun;
if strcmp(obj_fun_type,'Simultaneous')
    appDir = model_flooding.history_match.Cent_file_path; 
    name = model_flooding.history_match.Cent_file_name;
    temp_historymatch_variable_hold = model_flooding.history_match;
    cent_directory = fullfile(model_flooding.history_match.Cent_file_path, ...
        model_flooding.history_match.Cent_file_name);
    model_cent = Configure(cent_directory);
    model_cent = CreateGrid(model_cent);

function model = run_history_match_heterogeneous(x, model, type)
%
% DESCRIPTION: run the simulation case for history matching purposes of the
%              heterogeneous case
%
% SYNOPSIS:
%   model = run_history_match_homogeneous(x, model, type)
%
% PARAMETERS:
%   - x: iteration parameters
%   - model: struct on which the history match is running
%   - type: string used to turn of the gravity for the flooding 
%   experiments - example: 'ss' 
%
% RETURNS:
%   model - struct with the simulation results inside
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
% build the saturation functions
params_no_kr = get_params_no_kr(model);
model = Create_pc_history_match(x, model, params_no_kr);
model = Create_kr_history_match(x, model);
alpha = get_alpha(x, model);

% run homogeneous simulation
model = CreateFluid(model);
if strcmpi(type, 'ss')
    model = change_config_to_SS(model);
end
model = Run(model, false);

% run heterogeneous simulation
f_factor = f_factor_calculator(model, alpha, false, model.experiment.rock.het_index_mask);
model.experiment.rock.heterogeneous = true;
model = CreateGrid_heterogeneous(model);
model = CreateRock_heterogeneous(model, f_factor);

function [data,table] = ImportTable(file_path)
%
% DESCRIPTION: reads tabular data from kr, pc, schedule, ... tables in .txt
%              format
%
% SYNOPSIS:
%   [data,table] = ImportTable(fullFile)
%
% PARAMETERS:
%   fullFile - string path + file name (full file path) to the .txt file
%
% RETURNS:
%   data - array of the read data
%   table - table of the read data
%
% EXAMPLE:
%   [data,table] = ImportTable(".\kr_table.txt")
%
% ----------------------------------
% (c) 2020-2022
% Siroos Azizmohammadi
% Omidreza Amrollahinasab
% Montanuniversität Leoben, Austria
% Chair of Reservoir Engineering
% https://dpe.ac.at/
% ----------------------------------
%
%%
