function [procedure, schedule] = setup_startup(schedule, procedure, value_RPM, unit_RPM)

schedule.startupRPM.inputValue = value_RPM;
schedule.startupRPM.inputUnit = string(unit_RPM);  
schedule.startupRPM.value = (value_RPM * Convert(unit_RPM))...
    ^ 2 * schedule.centRad.value;
headers = procedure.Properties.VariableNames;
procedure_array = table2array(procedure); 
% schedule_in_rpm
SIR = sqrt(procedure_array(:,3)/schedule.centRad.value)...
    / Convert('rpm');
% procedure_table_in_rpm
PTIR = [procedure_array(:,1:2),SIR];
% start_up_rpm
SUR = sqrt(schedule.startupRPM.value/schedule.centRad.value)...
    / Convert('rpm');
% startupSlope
stSL = SUR / schedule.startupPeriod.value;
% added_schedule_row                 
ASRow = [];
% interval_between_steps
IBS = 20; % seconds
for i = 1 : height(PTIR)
    if i == 1
        % time_needed
        TN = PTIR(i,3) / stSL;
    else
        TN = ( PTIR(i,3) - PTIR(i-1,3)) / stSL; 
    end
    % residual_value
    RV = rem(TN, IBS);
    % number_of_steps
    NOS = floor(TN / IBS);
    % added_schedule_times
    AST = linspace(PTIR(i,1),PTIR(i,1) + NOS * IBS, NOS + 1);
    if i == 1
        % added_schedule_rpm
        ASrpm = linspace(0 ,NOS * IBS, NOS + 1) * stSL;
    else
        ASrpm = linspace(0 ,NOS * IBS, NOS + 1) * stSL + ...
            PTIR(i-1,3);   
    end
    for j = 1 : length(AST) - 1
        ASRow = [ASRow; ...
            [AST(j), AST(j + 1), ASrpm(j + 1)]];

function [headers,units] = SplitHeaders(cellArray)
% ask siroos for the docs
    for i = 1 : length(cellArray)
        header = cellArray{:,i};
        [header,unit] = minor_split(header);
        headers{:,i}  = header;
        units{:,i}    = unit;
    end
end

function [header,unit] = minor_split(str)     
    header = lower(str);
    idx = regexp([' ' header],'(?<=\s+)\S','start') - 1;
    unit = str(idx(end):end);
    idx(end) = idx(end) - 2;
    header = strcat(str(idx(1):idx(end))); 
    header = regexprep(header,'(\<[a-z])','${upper($1)}');
end

function appUnit = AppUnit(unit)
% ask siroos for the docs
    unit = lower(unit);

    % time    
    if(strcmp(unit,strcat('second')) || strcmp(unit,strcat('sec')) || strcmp(unit,strcat('s'))) 
        appUnit = 's'; 
        return;
    end    
    if(strcmp(unit,strcat('minute')) || strcmp(unit,strcat('min')) || strcmp(unit,strcat('m'))) 
        appUnit = 'min'; 
        return;
    end    
    if(strcmp(unit,strcat('hour')) || strcmp(unit,strcat('hr'))  || strcmp(unit,strcat('h'))) 
        appUnit = 'hr'; 
        return;
    end
    if(strcmp(unit,strcat('days')) || strcmp(unit,strcat('day'))  || strcmp(unit,strcat('d'))) 
        appUnit = 'day'; 
        return;
    end

    % length
    if(strcmp(unit,strcat('meter')) || strcmp(unit,strcat('m'))) 
        appUnit = 'm'; 
        return;
    end
    if(strcmp(unit,strcat('centimeter')) || strcmp(unit,strcat('cm'))) 
        appUnit = 'cm'; 
        return;
    end

    % volume
    if(strcmp(unit,strcat('m^3')) || strcmp(unit,strcat('m3'))) 
        appUnit = 'm^3'; 
        return;
    end
    if(strcmp(unit,strcat('cm^3')) || strcmp(unit,strcat('cm3'))) 
        appUnit = 'cm^3'; 
        return;
    end

    % volume rate
    if(strcmp(unit,strcat('m^3/second')) || strcmp(unit,strcat('m3/second')) || ...
       strcmp(unit,strcat('m^3/sec'))    || strcmp(unit,strcat('m3/sec'))    || ...

