%% Example: specification of boundary conditions
% In this example, we will show how to set boundary conditions to create
% pressure drop across a reservoir. For a rectangular model with
% homogeneous properties, this will create a linear pressure drop.
% The user can choose between different setups:
%
% # Rectangular model with Dirichlet boundary conditions on the left
% boundary and Neumann conditions on the right boundary, which will create
% a linear pressure drop
% # Rectangular model with hydrostatic boundary conditions and a fluid sink
% at the midpoint of the upper geological layer
% # Corner-point model with the same type of Dirichlet/Neumann boundary
% conditions on the left and right global boundaries
mrstModule add incomp

addpath('src');
setup = 3;

%% Define geometry
[nx,ny,nz] = deal(20, 20, 5);
[Lx,Ly,Lz] = deal(1000, 1000, 50);
switch setup
   case 1,
      gravity reset off
      G = cartGrid([nx ny nz], [Lx Ly Lz]);
   case 2,
      gravity reset on
      G = cartGrid([nx ny nz], [Lx Ly Lz]);
   case 3,
      gravity reset on
      G = processGRDECL(makeModel3([nx ny nz], [Lx Ly Lz/5]));
      G.nodes.coords(:,3) = 5*(G.nodes.coords(:,3) ...
                               - min(G.nodes.coords(:,3)));
end
G.nodes.coords(:,3) = G.nodes.coords(:,3) + 500;
G = computeGeometry(G);

%% Set rock and fluid data
rock.poro = repmat(.2, [G.cells.num, 1]);
rock.perm = repmat([1000, 300, 10].* milli*darcy(), [G.cells.num, 1]);
fluid = initSingleFluid('mu', 1*centi*poise, 'rho', 1014*kilogram/meter^3);

%% Compute transmissibility and initialize reservoir state
hT = simpleComputeTrans(G, rock);
[mu,rho] = fluid.properties();

%% Use of Peacemann well models
% In this example we will demonstrate how to set up a flow problems with
% two wells, one rate-controlled, vertical well and one horizontal well
% controlled by bottom-hole pressure. The reservoir is a regular box with
% homogeneous petrophysical properties.

mrstModule add incomp

%% Set up reservoir model
[nx,ny,nz] = deal(20,20,5);
G = computeGeometry( cartGrid([nx,ny,nz], [500 500 25]) );
rock  = makeRock(G, 100.*milli*darcy, .2);
fluid = initSingleFluid('mu', 1*centi*poise,'rho', 1014*kilogram/meter^3);
hT    = computeTrans(G, rock);

%% Add wells wells
W = verticalWell([], G, rock, 1, 1, 1:nz, 'Type', 'rate', 'Comp_i', 1,...
                'Val', 3e3/day, 'Radius', .12*meter, 'name', 'I');
disp('Well #1: '); display(W(1));

W = addWell(W, G, rock, nx : ny : nx*ny, 'Type', 'bhp', 'Comp_i', 1, ...
            'Val', 1.0e5, 'Radius', .12*meter, 'Dir', 'y', 'name', 'P');
disp('Well #2: '); display(W(2));

state = initState(G, W, 0);

%%
% We plot the wells to check if the wells are placed as we wanted them.
% (The plot will later be moved to subplot(2,2,1), hence we first find the
% corresponding axes position before generating the handle graphics).
subplot(2,2,1), pos = get(gca,'Position'); clf
plotGrid(G, 'FaceColor', 'none');
view(3), camproj perspective, axis tight off,
plotWell(G, W(1), 'radius',  1, 'height', 5, 'color', 'r');
plotWell(G, W(2), 'radius', .5, 'height', 5, 'color', 'b');

%% Assemble and solve system
gravity reset on;
state = incompTPFA(state, G, hT, fluid, 'wells', W);

%% Report results
% We move the plot of the grids and wells to the upper-left subplot. The
% producer inflow profile is shown in the upper-right and the cell
% pressures in the lower-left subplot. In the lower-right subplot, we show
% the flux intensity, which must be constructed by averaging over cell

%% Compare grid-orientation effects for TPFA/mimetic schemes

mrstModule add incomp mimetic streamlines diagnostics

% Rectangular reservoir with a skew grid.
G = cartGrid([41,20],[2,1]);
makeSkew = @(c) c(:,1) + .4*(1-(c(:,1)-1).^2).*(1-c(:,2));
G.nodes.coords(:,1) = 2*makeSkew(G.nodes.coords);
% G.nodes.coords = twister(G.nodes.coords);
% G.nodes.coords(:,1) = 2*G.nodes.coords(:,1);
G = computeGeometry(G);

% Homogeneous reservoir properties
rock = makeRock(G, 100*milli*darcy, .2);
pv   = sum(poreVolume(G,rock));

