function u=cuw(u0, cfl, dx, T, flux, dflux, boundary, lim)
if nargin==7,
    lim = @(r) max(0,min(1.3*r,min(.5+.5*r,1.3)));
end
limiter = @(a,b) lim(b./(a+1e-6)).*a;
dt = cfl*dx/max(abs(dflux(u0)));

[u,U] = deal(u0); f=0*u;
t = 0.0;
n = numel(u0);
i = 3:n-2;
j = 1:n-1;
while (t<T)
  if (t+dt > T), dt = (T-t); end
  t=t+dt;

  u = boundary(u,2);
  du = u(2:end)-u(1:end-1);
  phi = limiter(du(1:end-1),du(2:end));
  phi = phi([end 1:end 1]);     % only correct for periodic b.c.
  ur = u + .5*phi;  fr = flux(ur); dfr = dflux(ur);
  ul = u - .5*phi;  fl = flux(ul); dfl = dflux(ul);
  ap = max(max(dfr,dfl),0);
  am = min(min(dfr,dfl),0);
  mdf = max(ap,-am); mdf=max(mdf);
  f(j) = (ap(j).*fr(j) - am(j+1).*fl(j+1) ...
      + ap(j).*am(j+1).*(ul(j+1) - ur(j)))./ (ap(j)-am(j+1)+1e-6);
  U(i) = u(i) - dt/dx*(f(i)-f(i-1));

  U = boundary(U,2);
  du = U(2:end)-U(1:end-1);
  phi = limiter(du(1:end-1),du(2:end));
  phi = phi([end 1:end 1]);     % only correct for periodic b.c.
  ur = U + .5*phi;  fr = flux(ur); dfr = dflux(ur);
  ul = U - .5*phi;  fl = flux(ul); dfl = dflux(ul);
  ap = max(max(dfr,dfl),0);
  am = min(min(dfr,dfl),0);
  mdf = max(max(ap,-am),mdf); mdf=max(mdf);
  f(j) = (ap(j).*fr(j) - am(j+1).*fl(j+1) ...
      + ap(j).*am(j+1).*(ul(j+1) - ur(j)))./ (ap(j)-am(j+1)+1e-6);
  u(i) = .5*u(i) +.5*( U(i)-dt/dx*(f(i)-f(i-1)) );
  dt = cfl*dx/mdf;
end

function u=inflow(u,n)
if nargin==1
   u(1) = 1;
else
   u(1:n) = 1;
end

function u=lxf(u0,cfl,dx,T,flux,df,boundary)
u = u0; t = 0.0;
dt = cfl*dx/max(abs(df(u0)));
i = 2:numel(u0)-1;
while (t<T)
  if (t+dt > T)
     dt = (T-t);
  end
  t=t+dt;
  u = boundary(u);
  f = flux(u);
  u(i) = 0.5*(u(i+1)+u(i-1)) - 0.5*dt/dx*(f(i+1)-f(i-1));
  dt = cfl*dx/max(abs(df(u)));
end

function u=lxw(u0,cfl,dx,T,flux,df,boundary)
[u,U] = deal(u0);
t = 0.0;
dt = cfl*dx/max(abs(df(u0)));
i = 2:numel(u0)-1;
while (t<T)
  if (t+dt > T)
     dt = (T-t);
  end
  t=t+dt;
  u = boundary(u);
  f = flux(u);
  U(i) = 0.5*(u(i)+u(i+1)) - 0.5*dt/dx*(f(i+1)-f(i));
  U = boundary(U);
  f = flux(U);
  u(i) = u(i) - dt/dx*(f(i)-f(i-1));
  dt = cfl*dx/max(abs(df(u)));
end

function u=nt(u0,cfl,dx,T,flux,dflux,boundary,lim)
if nargin==7,
    lim = @(r) max(0,min(1.3*r,min(.5+.5*r,1.3)));
end
limiter = @(a,b) lim(b./(a+1e-6)).*a;
dt = cfl*dx/max(abs(dflux(u0)));

u=u0; t = 0.0;
while (t<T)
  if (t+dt > T), dt = .5*(T-t); end

  u = boundary(u,2);
  du = u(2:end)-u(1:end-1);
  s = limiter(du(1:end-1),du(2:end));
  s = s([end 1:end 1]);
  f = flux(u);
  df = f(2:end)-f(1:end-1);
  sigma = limiter(df(1:end-1),df(2:end));
  sigma = sigma([end 1:end 1]);     % only correct for periodic b.c.
  v = u - .5*dt/dx*sigma;
  g = flux(v) + .125*dx/dt*s;
  u(2:end) = .5*(u(1:end-1)+u(2:end)) - dt/dx*(g(2:end)-g(1:end-1));

  u = boundary(u,2);
  du = u(2:end)-u(1:end-1);
  s = limiter(du(1:end-1),du(2:end));
  s = s([end 1:end 1]);
  f = flux(u);
  df = f(2:end)-f(1:end-1);
  sigma = limiter(df(1:end-1),df(2:end));
  sigma = sigma([end 1:end 1]);     % only correct for periodic b.c.
  v = u - .5*dt/dx*sigma;
  g = flux(v) + .125*dx/dt*s;
  u(1:end-1) = .5*(u(1:end-1)+u(2:end)) - dt/dx*(g(2:end)-g(1:end-1));

  t = t+2*dt;
  dt = cfl*dx/max(abs(dflux(u)));
end

function u = periodic(u,n)
if nargin==1
    u(1) = u(end-1);
    u(end) = u(2);
else
    u(1:n) = u(end-2*n+1:end-n);
    u(end-n+1:end) = u(n+1:2*n);
end

