                nodes   = G.edges.nodes(mcolon(G.edges.nodePos(edges), ...
                                               G.edges.nodePos(edges+1)-1));
                % Number of triangles per face
                nTri    = diff(G.faces.edgePos);
                parents = rldecode((1:G.faces.num)', nTri, 1);
                % Face centroids
                xc      = G.faces.centroids(parents, :);

