classdef Polynomial
    % Polynomial class for basis functions in MRST
    properties
        k
        w
        dim
    end

    methods
        %-----------------------------------------------------------------%
        function poly = Polynomial(k, w)
            if nargin == 0
                poly.k = [0,0,0];
                poly.w = 1;
            elseif nargin == 1
                poly.k = k;
                poly.w = ones(size(k,1),1);
            elseif nargin == 2
                poly.k = k;
                poly.w = w;
            else
                error('Contructor requires 1 or 2 inputs');
            end 
            poly.dim = size(k,2);
        end

        %-----------------------------------------------------------------%
        function varargout = subsref(poly, x)
            switch x(1).type
                case '()'
                    x = x.subs{1};
                    npoly  = numel(poly);
                    npts   = size(x,1);
                    val    = zeros(npts, npoly);
                    for i = 1:numel(poly)
                        p = poly(i);
                        nterms = size(p.k,1);
                        v = 0;
                        for j = 1:nterms
                            v = v + p.w(j).*prod(x.^p.k(j,:),2);
                        end
                        val(:,i) = v;
                    end
                    [varargout{1:nargout}] = val;
                    return

