classdef DC_PoroelasticPropertyFunctions < StateFunctionGrouping
    % Default grouping for describing rock properties affected by
    % poroelasticity. Namely porosity and permeability. 
    properties
        PoroelasticMatrixPoro % scalar
        PoroelasticFracturePoro %
        Strain % tensor
        EffectiveStress % tensor
        TotalStress % tensor
        PoroelasticFracturePerm % scalar, for now
        PoroelasticFractureTransMult % scalar, for now
    end

    methods
        function props = DC_PoroelasticPropertyFunctions(model)
            props@StateFunctionGrouping();
            props.PoroelasticMatrixPoro = PoroelasticMatrixPoro(model);
            props.PoroelasticFracturePoro = PoroelasticFracturePoro(model);
            props.Strain = Strain(model);
            props.EffectiveStress = EffectiveStress(model);
            props.TotalStress = TotalStress(model);
            props.PoroelasticFracturePerm = PoroelasticFracturePerm(model);
            props.PoroelasticFractureTransMult = PoroelasticFractureTransMult(model);

            % Define storage field in state
            props.structName = 'DC_PoroelasticProps';
        end
    end
end

classdef EffectiveStress < StateFunction
    % Compute effective stress, depending on arguments make this cell-wise 
    % or over the domain
    properties
    end

    methods
        function gp = EffectiveStress(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'xd'}, 'state');
        end
        function v = evaluateOnDomain(prop, model, state)
            mechModel = model.mechModel;
            u = mechModel.operators.V_dir; 
            u(~mechModel.operators.isdirdofs) = model.getProp(state, 'xd');

            if(model.G.griddim == 2)
                lin_dim = 3; 
            elseif(model.G.griddim == 3)
                lin_dim = 6;
            else
                error('Wrong dimsension');
            end
            s = reshape(model.operators.global_stress * u, lin_dim, [])';

            try 
                switch mechModel.mech.deformation_reference
                    case 'cells'
                        v = s;
                    case 'domain'
                        v = s.*(model.G.cells.volumes...
                                ./prod(max(Dmodel.G.nodes.coords)));
                end
            catch
                % if nothing is specified just return cell-wise strains
                v = s;
            end
        end
    end
end

classdef PoroelasticFracturePerm < StateFunction
    % (Nonlinear)absolute permeability arising from poroelastic effects
    properties
    end

    methods
        function gp = PoroelasticFracturePerm(model, varargin)
            gp@StateFunction(model, varargin{:});
            if isfield(model.rock, 'nonLinearPerm')
                gp = gp.dependsOn({'PoroelasticFracturePoro'});
            end
        end
        function perm = evaluateOnDomain(prop, model, state)
            r = model.rock;
            if isfield(r, 'nonLinearPerm')
                poro_f = prop.getEvaluatedDependencies(state, 'PoroelasticFracturePoro');
                perm = prop.evaluateFunctionOnDomainWithArguments(r.nonLinearPerm, poro_f);
            end
        end
    end
end

classdef PoroelasticFracturePoro < StateFunction
    % Effective poroelastic fracture porosity 
    properties
    end

    methods
        function gp = PoroelasticFracturePoro(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'pressure', 'pressure_matrix', 'xd'}, 'state');
        end
        function poro_f = evaluateOnDomain(prop, model, state)
            % Get effective fracture porosity given changes in strain and 
            % matrix and fracture pressures. We assume a linear form where
            % refrence pressures and strain are zero.
            cM = model.mechModel.constitutive_coefficients_object;
            ref_poro_f = model.rock.poro;
            [p, pm, xd] = model.getProps(state, 'pressure', 'pressure_matrix',...
                                                'xd');
            mechTerm = model.computeStrainTerms(xd);
            poro_f = ref_poro_f + (mechTerm.fracture + cM.invQ.*pm...
                                   + cM.invN_f.*p); % mechTerm.fracture = b_f:E
        end
    end
end

classdef PoroelasticFractureTransMult < StateFunction
    % Transmissibility mulitplier arising from non-linear permeability
    properties
    end

    methods
        function gp = PoroelasticFractureTransMult(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'PoroelasticFracturePerm'});
        end
        function transMult = evaluateOnDomain(prop, model, state)
            N = model.G.faces.neighbors;
            intInx = all(N ~= 0, 2);
            N = N(intInx, :);
            perm_f0 = model.rock.perm;
            perm_f = prop.getEvaluatedDependencies(state, 'PoroelasticFracturePerm');
            transMult = zeros(size(N,1),1);
            harmonic = @(a,b) 1 ./ (1./a + 1./b);
            for n = 1:size(N,1)
                % K_new / K_ref at face
                transMult(n) = harmonic(perm_f(N(n,1)).val, perm_f(N(n,2)).val)... 
                               ./ harmonic(perm_f0(N(n,1)), perm_f0(N(n,2))); 
            end
        end
    end
end

classdef PoroelasticMatrixPoro < StateFunction
    % Effective poroelastic matrix porosity 
    properties
    end

    methods
        function gp = PoroelasticMatrixPoro(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'pressure', 'pressure_matrix', 'xd'}, 'state');
        end
        function m_poro = evaluateOnDomain(prop, model, state)
            % Get effective matrix porosity given changes in strain and 
            % matrix and fracture pressures. We assume a linear form where
            % refrence pressures and strain are zero. 
            cM = model.mechModel.constitutive_coefficients_object;
            ref_poro_m = model.rock_matrix.poro;
            [p, pm, xd] = model.getProps(state, 'pressure', 'pressure_matrix',...
                                                'xd');
            mechTerm = model.computeStrainTerms(xd);
            m_poro = ref_poro_m + (mechTerm.matrix + cM.invN_m.*pm...
                                   + cM.invQ.*p); % mechTerm.matrix = b_m:E
        end
    end
end

classdef Strain < StateFunction
    % Compute strain, depending on arguments make this cell-wise or over
    % the domain
    properties
    end

    methods
        function gp = Strain(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'xd'}, 'state');
        end
        function v = evaluateOnDomain(prop, model, state)
            mechModel = model.mechModel;
            u = mechModel.operators.V_dir; 
            u(~mechModel.operators.isdirdofs) = model.getProp(state, 'xd');

            if(model.G.griddim == 2)
                lin_dim = 3; 
            elseif(model.G.griddim == 3)
                lin_dim = 6;
            else
                error('Wrong dimsension');
            end
            e = reshape(model.operators.global_strain * u, lin_dim, [])';

            try 
                switch mechModel.mech.deformation_reference
                    case 'cells'
                        v = e;
                    case 'domain'
                        v = e.*(model.G.cells.volumes...
                                ./prod(max(Dmodel.G.nodes.coords)));
                end
            catch
                % if nothing is specified just return cell-wise strains
                v = e;
            end
        end
    end
end

classdef TotalStress < StateFunction
    % (Nonlinear)absolute permeability arising from poroelastic effects
    properties
    end

    methods
        function gp = TotalStress(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'pressure', 'pressure_matrix'}, 'state');
            gp = gp.dependsOn({'EffectiveStress'});
        end
        function v = evaluateOnDomain(prop, model, state)
            [p, pm] = model.getProps(state, 'pressure', 'pressure_matrix');
            effective_stress = prop.getEvaluatedDependencies(state, 'EffectiveStress');
            cM = model.mechModel.constitutive_coefficients_object;
            if model.G.griddim == 2
                pI = bsxfun(@times, p, [1, 1, 0]);
                pmI = bsxfun(@times, pm, [1, 1, 0]);
            else
                pI = bsxfun(@times, p, [1, 1, 1, 0, 0, 0]);
                pmI = bsxfun(@times, pm, [1, 1, 1, 0, 0, 0]);
            end
            v = effective_stress - cM.B_m.*pmI - cM.B_f.*pI;  
        end
    end
end

