%
% Modifications with regards to the original problem formulation of
% Firoozabadi and Thomas, 1990:
%   1. Consider only oil and water
%   2. Represent oil as dead oil with a typical compressibility
%   3. Matrix permeability is increased by the factor of 10 to achieve more 
%      pronounced differences with the dual porosity-dual permeability
%      model.
%
% Reference
% A. Firoozabadi, L. K. Thomas, Sixth SPE Comparative Solution Project: 
%   Dual-Porosity Simulators, Journal of Petroleum Technology 42 (06): 710�763.
%   DOI: https://doi.org/10.2118/18741-PA.

mrstModule add ad-core ad-props ad-blackoil dual-porosity deckformat

%% Choose between the dual porosity or dual porosity-dual permeability models
model_name = 'DP';
%model_name = 'DPDP';

%% Define the geometry
[Nx, Ny, Nz] = deal(10, 1, 5);
dx = 200*ft;
dy = 1000*ft;
dz = 50*ft;
G = cartGrid([Nx Ny Nz],[Nx*dx Ny*dy Nz*dz]);
G = computeGeometry(G); 

%% Rock properties
phim = 0.29;             % Matrix porosity
% Km = 1*milli*darcy;     % Matrix permeability
Km = 10*milli*darcy;     % Increased matrix permeability
phif = 0.01;             % Fracture porosity
Kf1 = 10*milli*darcy;    % Fracture permeability for layers 1-2
Kf2 = 90*milli*darcy;    % Fracture permeability for layers 3
Kf3 = 20*milli*darcy;    % Fracture permeability for layers 4-5

Kf = ones(Nx * Ny * Nz, 1);
Kf(1:2*Nx*Ny) = Kf1;
Kf(2*Nx*Ny+1:3*Nx*Ny) = Kf2;
Kf(3*Nx*Ny+1:5*Nx*Ny) = Kf3;

% Create the rock structures for fractures and the matrix
rock_fracture = makeRock(G, Kf, phif);

classdef myEclipseTwoPhaseTransferFunction < TransferFunction
    %% A corrected version of the Eclipse two-phase transfer function.
    properties
        shape_factor_object
        shape_factor_name
    end

    methods

        function transferfunction = myEclipseTwoPhaseTransferFunction(shape_factor_name,block_dimension)

            transferfunction = transferfunction@TransferFunction();
            transferfunction.nphases = 2;

            if (nargin<1)
                %% No information about shape factor is provided so we set it to 1
                transferfunction.shape_factor_name = 'ConstantShapeFactor';
                block_dimension = [1,1,1];
                shape_factor_value = 1;
                shape_factor_handle = str2func(transferfunction.shape_factor_name);
                transferfunction.shape_factor_object = shape_factor_handle(block_dimension,shape_factor_value);
            else
                if (nargin<2)
                    msg = ['ERROR: If you provide the shape factor name, make sure to',...
                          'provide also the fracture spacing, [lx,ly,lz]'];
                    error(msg);
                else
                    transferfunction.shape_factor_name = shape_factor_name;
                    shape_factor_handle = str2func(transferfunction.shape_factor_name);
                    transferfunction.shape_factor_object = shape_factor_handle(block_dimension);
                end
            end


        end


        function [Talpha] = calculate_transfer(ktf,model,fracture_fields,matrix_fields)

            %% All calculate_transfer method should have this call. This is a "sanity check" that
            % ensures that the correct structures are being sent to calculate the transfer
            ktf.validate_fracture_matrix_structures(fracture_fields,matrix_fields);

            %% The varibles
            pom = matrix_fields.pom;

classdef VariableShapeFactor < ShapeFactor
    % Class representing a shape factor which is potentially different 
    % for every cell.    
    % 
    % INITIALIZATION:
    %    Initialized from a transfer function constructor
    %
    % METHODS:
    %   calculate_shape_factor - Return the shape factors for all cells

    % ============================= Class properties ==========================
    properties
        smin   % The (linear) shape factor
    end

    % ============================== Public methods ===========================
    methods

        % Constructor
        function shapefactor = VariableShapeFactor(par) %, qmax, pow)

            % Interpret the input parameters as [rock.smin block_dimension]
            smin = par(:, 1);
            block_dimension = par(:, 2:4);

            % Call superclass constructor to set the block_dimension
            shapefactor = shapefactor@ShapeFactor(block_dimension);

            % Initialize class properties 
            shapefactor.smin = smin;

        end

        % Return the shape factors times matrix permeability for all cells
        function [sigma] = calculate_shape_factor(sf, model)      

            % Use the average matrix permeability
            kx = model.rock_matrix.perm(:,1);
            try
                ky = model.rock_matrix.perm(:,2);
                kz = model.rock_matrix.perm(:,3);
            catch
                ky = model.rock_matrix.perm(:,1);
                kz = model.rock_matrix.perm(:,1);
            end

