classdef ECPATableCompositionalMixture < ECPACompositionalMixture
    % Create MRST compositional mixture from stored tables
    properties

    end

    methods
        function mix = ECPATableCompositionalMixture(names, outnames)
            % Create fluid from names
            %
            % SYNOPSIS:
            %   f = ECPATableCompositionalMixture({'Water','CarbonDioxide','Na+','Cl-'});
            %
            % PARAMETERS:
            %   names    - Cell array of valid names. See `getFluidList` for
            %              valid names.
            %   outnames - The names the components will have in output
            %              (optional).
            % RETURNS:
            %   mix - Initialized compositional mixture.
            if ischar(names)
                names = {names};
            end
            if nargin == 1
                outnames = names;
            else
                if ischar(outnames)
                    outnames = {outnames};
                end
                assert(numel(names) == numel(outnames))
            end

            ncomp = numel(names);
            [Tcrit, Pcrit, rhocrit, acc, molarMass, b, a0, c1, epsilonAB,...
                betaAB, alpha0, mu0, d, rborn, hyd, charge, parachor, c] ...
                = deal(zeros(1, ncomp));

            fluids = eCPAPropFluidsStructs();
            validChoices = ECPATableCompositionalMixture.getFluidList();

            ok = ismember(lower(names), lower(validChoices));

            if ~all(ok)
                s ='Unable to create fluid. The following names were not known to CoolProps table: ';
                msg = [s, sprintf('%s ', names{~ok})];

classdef ECPAGenericNaturalVariablesModel < ECPANaturalVariablesCompositionalModel & GenericReservoirModel
    properties

    end

    methods
        function model = ECPAGenericNaturalVariablesModel(varargin)
            model = model@ECPANaturalVariablesCompositionalModel(varargin{:});
            model.OutputStateFunctions = {'ComponentTotalMass'};
        end

        function [problem, state] = getEquations(model, state0, state, dt, drivingForces, varargin)
            [problem, state] = getEquations@ReservoirModel(model, state0, state, dt, drivingForces, varargin{:});
        end

        function [eqs, names, types, state] = getModelEquations(model, state0, state, dt, drivingForces)
            % Discretize
            [eqs, flux, names, types] = model.FlowDiscretization.componentConservationEquations(model, state, state0, dt);
            src = model.FacilityModel.getComponentSources(state);
            [pressures, sat, mob, rho, X] = model.getProps(state, 'PhasePressures', 's', 'Mobility', 'Density', 'ComponentPhaseMassFractions');
            comps = cellfun(@(x, y) {x, y}, X(:, model.getLiquidIndex), X(:, model.getVaporIndex), 'UniformOutput', false);


            [eqs, ~, bcs] = model.addBoundaryConditionsAndSources(eqs, names, types, state, ...
                                                             pressures, sat, mob, rho, ...
                                                             {}, comps, ...
                                                             drivingForces);
            % state.diffusionFlux = bcs.bc.diffusionFlux;
            % Add sources
            eqs = model.insertSources(eqs, src);

            % Assemble equations
            if isfield(model.rock, 'Mechanisms') && isfield(model.rock.Mechanisms,'diffusion')
                xM = X(:, model.getLiquidIndex);
                sO = sat{model.getLiquidIndex};
                flag = model.getProps(state, 'PhaseUpwindFlag');
                upco = flag{model.getLiquidIndex};
                rhoO = rho{model.getLiquidIndex};
            end
            for i = 1:numel(eqs)
                eqs{i} = model.operators.AccDiv(eqs{i}, flux{i});
                if isfield(model.rock, 'Mechanisms') && isfield(model.rock.Mechanisms,'diffusion')
                    % add diffusion:
                    So_poro = model.operators.faceUpstr(upco,sO.*model.rock.poro);
                    Jo = model.operators.Div(model.operators.T_diff{i}./model.rock.tau.*So_poro.*model.operators.Grad(xM{i}.*rhoO));

