classdef ECPAPhaseCompressibilityFactorsLV < StateFunction
    % Compressibility factors for liquid-vapor system (multiplier to ideal
    % gas law)
    properties
        useCompactEvaluation = true;
    end

    methods
        function gp = ECPAPhaseCompressibilityFactorsLV(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'PhaseMixingCoefficients', 'ComponentPhaseMoleFractions'});
            gp = gp.dependsOn({'pressure', 'T'}, 'state');
            gp.label = 'Z_\alpha';
        end

        function v = evaluateOnDomain(prop, model, state)
            if isfield(state, 'cellJacMap')
                arg = {state.cellJacMap};
            else
                arg = {};
            end
            nph = model.getNumberOfPhases();
            eos = model.EOSModel;
            [p, T] = model.getProps(state, 'pressure', 'T');
            [mix, mf] = prop.getEvaluatedDependencies(state, 'PhaseMixingCoefficients', 'ComponentPhaseMoleFractions');
            L_ix = model.getLiquidIndex();
            V_ix = model.getVaporIndex();
            isEoS = model.getEoSComponentMask();

            x = mf(isEoS, L_ix);
            y = mf(isEoS, V_ix);

            L_mix = mix{L_ix};
            V_mix = mix{V_ix};

            [~, v_L, XA_L, XC_L] = eos.computeCompressibilityZ(p, T, x, L_mix.A, L_mix.B, L_mix.Ai, L_mix.Si, L_mix.Tr, true);
            [v_L, XA_L, XC_L] = eos.setvDerivatives(T, p, x, L_mix.A, L_mix.B, v_L, XA_L, XC_L, L_mix.Tr, arg{:});
            R = 8.314462618;
            Z_L = p.*v_L./(R .* T);
            twoPhase = model.getTwoPhaseFlag(state);
            if prop.useCompactEvaluation && ~all(twoPhase)
                Z_V = Z_L;
                v_V = v_L;
                XA_V = XA_L;
                XC_V = XC_L;

classdef ECPAPhaseMixingCoefficientsLV < StateFunction
    % Mixing coefficients for liquid-vapor system
    properties
        useCompactEvaluation = true;
    end

    methods
        function gp = ECPAPhaseMixingCoefficientsLV(model, varargin)
            gp@StateFunction(model, varargin{:});
            gp = gp.dependsOn({'T'}, 'state');
            gp = gp.dependsOn('ComponentPhaseMoleFractions');
            gp.label = 'Si A B Ai Tr';
        end

        function v = evaluateOnDomain(prop, model, state)
            eos = model.EOSModel;
            T = model.getProps(state, 'temperature');
            xy = prop.getEvaluatedDependencies(state, 'ComponentPhaseMoleFractions');
            L_ix = model.getLiquidIndex();
            V_ix = model.getVaporIndex();
            isEoS = model.getEoSComponentMask();
            nph = size(xy, 2);
            v = cell(1, nph);

            x = xy(isEoS, L_ix);
            y = xy(isEoS, V_ix);

            [A_ij, Ai, Tr] = eos.getMixingParameters(T, iscell(x));
            [Si_L, A_L, B_L] = eos.getPhaseMixCoefficients(x, A_ij);
            twoPhase = model.getTwoPhaseFlag(state);
            if prop.useCompactEvaluation && iscell(y) && ~all(twoPhase)
                A_V = A_L;
                B_V = B_L;
                Si_V = Si_L;
                if any(twoPhase)
                    y_2ph = cellfun(@(x) x(twoPhase), y, 'UniformOutput', false);
                    A_ij = cellfun(@(x) x(twoPhase), A_ij, 'UniformOutput', false);
                    [Si, A_V(twoPhase), B_V(twoPhase)] = eos.getPhaseMixCoefficients(y_2ph, A_ij);
                    for i = 1:numel(Si_V)
                        Si_V{i}(twoPhase) = Si{i};
                    end
                end
            else
                [Si_V, A_V, B_V] = eos.getPhaseMixCoefficients(y, A_ij);
            end

function K = eCPAestimateEquilibriumWilson(eos, p, T)
% Estimate equilibrium constant for a given pressure and temperature

