        function du = getQoI(qoi, seed)
            du = qoi.levelQoIs{end}.ResultHandler{seed};
            if numel(qoi.levelQoIs) == 2
                u0 = qoi.levelQoIs{1}.ResultHandler{seed};
                for fn = qoi.names
                    du.(fn{1}) = du.(fn{1}) - u0.(fn{1});
                end
                du.cost = du.cost + u0.cost;
            end
            qoi.ResultHandler{seed} = du;
        end

    end
end

