classdef MCSimulator < MRSTEnsemble

    properties(Access = protected)
        numSamples = 0
        estimate   = 0
        variance   = 0
        cost       = 0
        rmse       = inf
        history    = {}
        included
    end

    methods

        %-----------------------------------------------------------------%
        function mc = MCSimulator(mrstExample, samples, qoi, varargin)
            assert(numel(qoi.names) == 1, 'MCSimulator only supports one qoi');
            mc = mc@MRSTEnsemble(mrstExample, samples, qoi, varargin{:});
            mc.figures.progressMC = [];
        end

        %-----------------------------------------------------------------%
        function runSimulation(mc, varargin)
            opt = struct('range'       , inf , ...
                         'batchSize'   , inf , ...
                         'maxSamples'  , 10  , ...
                         'minSamples'  , 2   , ...
                         'tolerance'   , -inf, ...
                         'relTolerance', -inf, ...
                         'prompt'      , true, ...
                         'plotProgress', true);
            opt = merge_options(opt, varargin{:});
            assert(xor(isfinite(opt.tolerance), isfinite(opt.relTolerance)), ...
                   'Choose either relative or absolute tolerance');
            % Check for computed samples
            range = mc.getComputedSampleRange();
            n     = numel(range);
            if n > 0 && opt.prompt
                % We found computed samples - ask user if they should be
                % included in the estimate
                prompt = sprintf(['Found %d QoIs for this problem. '   , ...
                                  'Would you like to include these in ', ...
                                  'your estimate (y)? If not, I will ' , ...
                                  'delete them y/n [y]: '], n          );
                str = input(prompt,'s');

classdef MLMCSimulator < MCSimulator

    properties
        levels
    end

    methods
        %-----------------------------------------------------------------%
        function mlmc = MLMCSimulator(setup, samples, qoi, levels, varargin)
            mlmc = mlmc@MCSimulator(setup, samples, qoi, varargin{:});
            mlmc.levels = cell(numel(levels), 1);
            for i = 1:mlmc.numLevels
                lix = max(i-1,1):i;
                % Level QoIs will be stored in a subfolder `level-<levelNo>`
                directory = fullfile(mlmc.getDataPath(), ...
                            ['level-', num2str(levels{lix(end)}.levelNo)]);
                mlmc.levels{i} = MCLevelSimulator(setup, samples, qoi, levels(lix), ...
                                                  varargin{:}           , ...
                                                  'directory', directory);
            end
        end

        %-----------------------------------------------------------------%
        function range = runBatch(mlmc, varargin)
            opt = struct('batchSize', []);
            [opt, extra] = merge_options(opt, varargin{:});
            range = nan(sum(opt.batchSize), 1);
            if mlmc.verbose
                if mlmc.numSamples == 0
                    s = 'warmup';
                else
                    s = 'iteration';
                end
                bs = num2str(opt.batchSize');
                fprintf(['Running multilevel Monte Carlo %s ', ...
                         'with (%s) samples\n\n'], s, bs     );
            end
            for i = 1:mlmc.numLevels
                if opt.batchSize(i) > 0
                    maxId = mlmc.getLargestSeed();
                    lrange = (1:opt.batchSize(i)) + maxId;
                    mlmc.levels{i}.runBatch('range', lrange, extra{:});
                    range((1:opt.batchSize(i)) + sum(opt.batchSize(1:i-1))) = lrange;
                    while ~all(mlmc.levels{i}.getSimulationStatus(lrange) > 0)
                        pause(0.05);

