%}

V = zeros([sum(sz .^ 2), 1]);
[p1, p2] = deal(0);

for b = 1 : numel(sz),
    n  = sz(b);
    n2 = n * n;
    i  = p1 + (1 : n);

    V(p2 + (1 : n2)) = inv(full(A(i, i)));

    p1 = p1 + n;
    p2 = p2 + n2;
end

iA = blockDiagMatrix(V, sz);
clear V;

