function I = isothermal_compressibility(p, p0, E, F)
% Function that computes the isothermal compressibility equations (7) and
% (14) in Spivey et al., 2004

    a = E.*(p./p0) + F;
    tol = 1e-16;
    a(a<tol) = tol;
    I = 1./E .* log(a);

end

