    methods
        %-----------------------------------------------------------------%
        function cf = WellboreSurfaceRate(model)

            cf@StateFunction(model);
            cf = cf.dependsOn({'ComponentPhaseFlux', 'PhaseUpwdinFlag'}, 'FlowPropertyFunctions');
            cf = cf.dependsOn({'SurfaceDensity'}, 'PVTpropertyFunctions');
            cf.label = 'q_s';

        end
