function props  = getPropertiesReservoirSide(model, state, force, is_bc)
    [h, p, T, s, rho, mob] = model.getProps(state, 'enthalpy'                 , ...
                                                   'pressure'                 , ...
                                                   'Temperature'              , ...
                                                   's'                        , ...
                                                   'Density'                  , ...
                                                   'Mobility'                 , ...
                                                   'FluidHeatTransmissibility', ...
                                                   'RockHeatTransmissibility' );

    if is_bc
        faces = force.face;
        cells = sum(model.G.faces.neighbors(faces,:),2);
    else
        cells = force.cell;
        fpos  = mcolon(model.G.cells.facePos(cells), model.G.cells.facePos(cells+1)-1);
        faces = model.G.cells.faces(fpos);
        nf    = diff(model.G.cells.facePos); nf = nf(cells);
        [ii, jj] = blockDiagIndex(ones(numel(nf),1), nf);
        S        = sparse(ii, jj, 1);
        map      = @(x) (S*x)./nf;
    end
    % Extract BC cell values
    getBCVal = @(v) cellfun(@(v) v(cells), v, 'UniformOutput', false);
    p   = p(cells);
    T   = T(cells);

function forces = getHeatFluxFromSources(model, forces, drivingForces)
%Add heat flux from boundary conditions

    % Early return if no BCs are given
    [forces.bc.heatFlux, forces.src.heatFlux] = deal([]);
    if ~isempty(forces.bc.sourceCells)
        bc = drivingForces.bc;
        propsRes = bc.propsRes;
        propsBC  = bc.propsForce;
        [qAdv, q] = computeAdvectiveHeatFlux( ...
            model, propsRes, propsBC, forces.bc.phaseMass);
        is_inj = value(q) >= 0;
        qCond = computeConductiveHeatFlux(propsRes, propsBC, bc, is_inj);
        forces.bc.advHeatFlux = q;
        forces.bc.condHeatFlux = qCond;
        forces.bc.heatFlux = qAdv + qCond;
    end

    if ~isempty(forces.src.sourceCells)
        src = drivingForces.src;
        propsRes  = src.propsRes;
        propsSrc  = src.propsForce;
        [qAdv, q] = computeAdvectiveHeatFlux( ...
            model, propsRes, propsSrc, forces.src.phaseMass);
        is_inj = value(q) >= 0;
        qCond = computeConductiveHeatFlux(propsRes, propsSrc, src, is_inj);
        forces.src.advHeatFlux = q;
        forces.src.condHeatFlux = qCond;
        forces.src.heatFlux = qAdv + qCond;
    end

end

