function [q, qph] = computeAdvectiveHeatFlux(model, propsRes, propsBC, src)

    nph = model.getNumberOfPhases();
    q   = 0;
    qph = cell(1,nph);
    hbc = model.getProps(propsBC , 'PhaseEnthalpy');
    hr  = model.getProps(propsRes, 'PhaseEnthalpy');    
    for i = 1:nph
        inflow = src{i} > 0;
        h      = inflow.*hbc{i} + ~inflow.*hr{i};
        qph{i} = src{i}.*h;

