%% 2D Hydrogen Storage: PVT Table Generation and Black-Oil Simulation
% ===========================================================================
% This example demonstrates how to generate and use tabulated PVT data for
% hydrogen storage simulations using MRST's black-oil model. The script shows:
%
% 1. Generation of SGOF tables for relative permeability
% 2. Creation of solubility tables for H2-water systems  
% 3. PVT table generation using equation of state
% 4. Black-oil simulation with tabulated data
%
% Key features:
% - Dome-shaped 2.5D reservoir geometry
% - Three geological layers (underburden, reservoir, caprock)
% - Region-dependent relative permeability
% - Miscible and immiscible flow options
%% Load Required MRST Modules
mrstModule add ad-core ad-blackoil ad-props mrst-gui spe10 deckformat h2store

%% Initialize Gravity
gravity reset on
grav = [0, 0, -norm(gravity)];

%% Define Grid (2D X-Z Domain)
cartDims = [100, 1, 20];                  % Grid dimensions
physDims = cartDims .* [0.5, 1, 1.25];    % Physical dimensions in ft
G = cartGrid(cartDims, physDims);

%% Apply Dome-Shaped Deformation in Z-Direction
x = G.nodes.coords(:,1);
z = G.nodes.coords(:,3);
G.nodes.coords(:,3) = z + 10 * exp(-((x - physDims(1)/2).^2) / (2 * (physDims(1)/8)^2));
G.nodes.coords(:,3) = G.nodes.coords(:,3) - 35;  % Shift dome downward
G = computeGeometry(G);

%% Define Geological Regions
[~, ~, k] = ind2sub(cartDims, G.cells.indexMap);
underburden = k <= 6;
reservoir   = k > 6 & k <= 14;
caprock     = k > 14;

% %% Plot Geological Layers
% clf;
% plotGrid(G, underburden, 'FaceColor', 'g'); hold on
% plotGrid(G, reservoir,   'FaceColor', 'r');
% plotGrid(G, caprock,     'FaceColor', 'b');

function [totalGasVolume, H2InWater, vH2InGas] = computeGasVolumes(model, states, steps)
    % Get phase names and find indices for liquid and gas
    names = model.getPhaseNames();
    nph = model.getNumberOfPhases;               
    for ph = 1:nph    
        switch names(ph)
            case 'O'
                L_ix = ph;
            case 'G'
                V_ix = ph;
        end
    end
    % Preallocate arrays for efficiency
    H2InWater = cell(length(steps), 1);
    vH2InGas = cell(length(steps), 1);
    totalGasVolume = cell(length(steps), 1);

    % Loop through each step to compute gas volumes
    for i = 1:length(steps) 
        step = steps(i);
        H2InWater{i} = states{step}.PVTProps.ShrinkageFactors{L_ix} .* ...
                          states{step}.s(:, V_ix) .* ...
                          model.G.cells.volumes .* ...
                          states{step}.rs;
        vH2InGas{i} = states{step}.PVTProps.ShrinkageFactors{V_ix} .* ...
                         model.G.cells.volumes .*states{step}.s(:, V_ix);
        totalGasVolume{i} = H2InWater{i} + vH2InGas{i}; % Total gas volume in the reservoir
    end
end

