function [ p, dp ] = minc_proximity_function( x, L )
%PROXIMITY Summary of this function goes here
%   Detailed explanation goes here

    min_x = min(L);

    dimension = length(L);
    switch dimension
        case 1
            u = 2*x/L(1);
            if x < min_x
                p = u;
            else
                p = 1;
            end
            dp = 2/L(1);
        case 2
            u = 2*x/L(1);
            v = 2*x/L(2);
            if x < min_x
                p = u + v - u*v;
            else
                p = 1;
            end
            dp = (-8*x + 2*L(1) + 2*L(2))/(L(1)*L(2));
        case 3
            u = 2*x/L(1);
            v = 2*x/L(2);
            w = 2*x/L(3);
            if x < min_x
                p = u + v + w - u*v - u*w - v*w + u*v*w;
            else
                p = 1;
            end
            dp = (24*x^2 - 8*(L(1)+L(2)+L(3))*x +...
                2*(L(1)*L(2) + L(1)*L(3) + L(2)*L(3)))...
                /(L(1)*L(2)*L(2));
        otherwise
            error('Too many entries for fracture spacing L');
    end


end

function [ dp ] = minc_proximity_function_dev( x, L )
%PROXIMITY Summary of this function goes here
%   Detailed explanation goes here

    dimension = length(L);
    switch dimension
        case 1
            dp = 2/L(1);
        case 2
            dp = (-8*x + 2*L(1) + 2*L(2))/(L(1)*L(2));
        case 3
            dp = (24*x^2 - 8*(L(1)+L(2)+L(3))*x +...
                2*(L(1)*L(2) + L(1)*L(3) + L(2)*L(3)))...
                /(L(1)*L(2)*L(2));
        otherwise
            error('Too many entries for fracture spacing L');
    end


end

function [ dist, area ] = shell_properties( volume_fractions,block_dimensions )
%shell_properties Summary of this function goes here
%   Detailed explanation goes here

x = get_shell_boundary_pos_from_volume_fractions( volume_fractions(1:end-1), block_dimensions );

dist = zeros(length(volume_fractions),1);
area = zeros(length(volume_fractions),1);

for i=1:length(volume_fractions)-1
    dist(i) = (x(i+1)-x(i))/2;
    area(i) = minc_proximity_function_dev(x(i),block_dimensions)*prod(block_dimensions);
end

dist(end) = x(end)-x(end-1);
area(end) = minc_proximity_function_dev(x(end-1),block_dimensions)*prod(block_dimensions);

end

