classdef FracturedDomainPhaseFlux < StateFunction
    properties

    end

    methods
        function fm = FracturedDomainPhaseFlux(model)
            fm@StateFunction(model);
            fm = fm.dependsOn({'FaceMobility', 'PermeabilityPotentialGradient'});
        end


        function v = evaluateOnDomain(prop, model, state)

            [mob, kgrad] = prop.getEvaluatedDependencies(state,...
                'FaceMobility', 'PermeabilityPotentialGradient');

            %% Standard flux evaluation
            v = cellfun(@(x,y)-x.*y, mob, kgrad, 'UniformOutput', false);

            %% Compute fluxes between mutli-continuum domains
            for j = 1:length(model.G.FracturedDomains.domains)
                dom = model.G.FracturedDomains.domains{j};
                if(strcmp(dom.type,'multi_continuum'))
                    ids = dom.global_connection_ids;
                    vf = dom.transfer_model.transfer(model, state, j);
                    for i = 1:numel(mob)
                        v{i}(ids) = vf{i};
                    end
                end
            end
        end
    end
end

classdef FracturedDomainPoreVolume < StateFunction
    % Effective pore-volume after pressure-multiplier
    properties
    end

    methods
        function gp = FracturedDomainPoreVolume(model, varargin)
            gp@StateFunction(model, varargin{:});
            if isfield(model.fluid, 'pvMultR')
                gp = gp.dependsOn({'pressure'}, 'state');
            end
        end
        function pv = evaluateOnDomain(prop, model, state)
            % Get effective pore-volume, accounting for possible
            % rock-compressibility
            f = model.fluid;
            pv = model.operators.pv;
            if isfield(f, 'pvMultR')
                p = model.getProp(state, 'pressure');
                pvMult = prop.evaluateFunctionOnDomainWithArguments(f.pvMultR, p);
                pv = pv.*pvMult;
            end
            for i = 1:length(model.G.FracturedDomains.domains)

                dom = model.G.FracturedDomains.domains{i};
                if strcmp(dom.type,'multi_continuum')
                    v = model.G.cells.volumes(dom.region);
                    if isfield(dom.fluid, 'pvMultR')
                        p = model.getProp(state, 'pressure');
                        pvMult = prop.evaluateFunctionOnDomainWithArguments(dom.fluid.pvMultR, p);
                        v = v.*pvMult(dom.connection_cell_list);                    
                    end                    
                else
                    ap = dom.rock.aperture;
                    area = model.G.faces.areas(dom.region);
                    v = ap.*area;
                end
                pvdom = dom.rock.poro.*v;
                pv = [pv; pvdom];
            end
        end
    end
end

classdef FracturedDomainPVTPropertyFunctions < PVTPropertyFunctions
    % PVT property functions for fractured domains

    methods
        function props = FracturedDomainPVTPropertyFunctions(model)
            % Add in pv for fracture cells to please PoreVolume constructor
            pv0 = model.operators.pv;
            model.operators.pv = [model.operators.pv; 
                   ones(model.G.cells.num - numel(model.operators.pv), 1)];
            % Call parent constructor
            props@PVTPropertyFunctions(model);
            % Set pv back to what it was
            model.operators.pv = pv0;
            % Replace pore volume
            pvt = props.getRegionPVT(model);
            props = props.setStateFunction('PoreVolume', FracturedDomainPoreVolume(model, pvt));
        end
    end

end

