classdef LimAzizShapeFactor < ShapeFactor
    %LIM_AZIZ_SHAPE_FACTOR
    %
    % calculates the shape factor handling anisotropic permeability
    % dimensions are k.L^-2
    % when the permeability is isotropic this formula collapses to
    % km.sigma as quoted in the literature

    properties

    end

    methods
        function shapefactor = LimAzizShapeFactor(block_dimension)
            has_permeability = 1;
            shapefactor = shapefactor@ShapeFactor(block_dimension,...
                                                  has_permeability);
        end

        function [sigma] = calculateShapeFactor(sf, rock)

            kx = rock.perm(:,1);
            try
                ky = rock.perm(:,2);
                kz = rock.perm(:,3);
            catch
                ky = rock.perm(:,1);
                kz = rock.perm(:,1);
            end
            lx = sf.block_dimension(:,1);
            ly = sf.block_dimension(:,2);
            lz = sf.block_dimension(:,3);

            kavg = (1/3)*(kx + ky + kz);

            sigma = kavg.*((pi^2)./(kx.*ky.*kz).^(1/3)).*...
                           (kx./(lx.^2)+ky./(ly.^2)+kz./(lz.^2));

        end
    end
end

classdef MincShapeFactor < ShapeFactor
    %MINC_SHAPE_FACTOR
    %

    properties
        opt
    end

    methods

        function shapefactor = MincShapeFactor(block_dimension, varargin)
            opt = struct('volume_fractions', [], ...
                         'domains', []);
            has_permeability = 1;
            shapefactor = shapefactor@ShapeFactor(block_dimension,...
                                                  has_permeability);
            shapefactor.opt = merge_options(opt, varargin{:});
        end

        function [sigma] = calculateShapeFactor(sf, rock)

            [ dist, area] = shell_properties( sf.opt.volume_fractions, sf.block_dimension );

            %TODO anisotropic permeability 
            kx = rock.perm(:,1);


            if sf.opt.domains(1)==0
                sigma = area(sf.opt.domains(2))*kx/dist(1)/prod(sf.block_dimension);
            else
                sigma = area(sf.opt.domains(2))*kx...
                    /(dist(sf.opt.domains(1)) + dist(sf.opt.domains(2)))...
                    /prod(sf.block_dimension);
            end
        end
    end
end

classdef WarrenRootShapeFactor < ShapeFactor
    %WARREN_ROOT_SHAPE_FACTOR
    %
    % calculates the shape factor handling anisotropic permeability
    % dimensions are k.L^-2
    % when the permeability is isotropic this formula collapses to
    % km.sigma as quoted in the literature
    %
    %Warren and Root 1963
    % sigma = 4n(n+1)/l^2
    % where n is the sets of normal fractures
    % here n is assumed to be 1

    properties

    end

    methods
        function shapefactor = WarrenRootShapeFactor(block_dimension)
            has_permeability = 1;
            shapefactor = shapefactor@ShapeFactor(block_dimension,...
                                                has_permeability);
        end

        function [sigma] = calculateShapeFactor(sf, rock)
            kx = rock.perm(:,1);
            try
                ky = rock.perm(:,2);
                kz = rock.perm(:,3);
            catch
                ky = rock.perm(:,1);
                kz = rock.perm(:,1);
            end
            lx = sf.block_dimension(:,1);
            ly = sf.block_dimension(:,2);
            lz = sf.block_dimension(:,3);
            assert(lx==ly && lx==lz,...
                'lx!=ly!=lz Warren&Root shape factor assumes equal matrix block lengths')

            kavg = (1/3)*(kx + ky + kz);

            sigma = 60*kavg./lx.^2;
        end
    end
end

function Trans = calculateTransmissibilitiesDFM(model) 

    fdom = model.G.FracturedDomains.domains{end};
    %% compute half transmissibilities for fracture virtual cells 
    half_trans = struct();
    half_trans.fracfrac = zeros(fdom.ncells,1);
    half_trans.fracmat = zeros(fdom.ncells,1);
    half_trans.matfrac_left = zeros(fdom.ncells,1);
    half_trans.matfrac_right = zeros(fdom.ncells,1);

    areas = model.G.faces.areas(fdom.region);

    %% Convenience variables
    k = fdom.rock.perm;
    a = fdom.rock.aperture;

    %% Setting frac-frac half trans
    half_trans.fracfrac = (a.*k)./(areas/2);

    %% Setting frac-mat half trans
    half_trans.fracmat = (2*areas.*k)./a;


    %% Setting mat-frac half trans
    matrix_cells_left = model.G.faces.neighbors(fdom.region,1);
    matrix_cells_right = model.G.faces.neighbors(fdom.region,2);
    half_trans.matfrac_left =  zeros(size(fdom.region));
    half_trans.matfrac_right =  zeros(size(fdom.region));


    for kk=1:size(fdom.region,1)
        facePos = model.G.cells.facePos(matrix_cells_left(kk)):model.G.cells.facePos(matrix_cells_left(kk)+1)-1;
        cfaces = model.G.cells.faces(facePos);
        Tid = facePos(find(cfaces==fdom.region(kk)));
        half_trans.matfrac_left(kk) = model.G.FracturedDomains.half_trans(Tid);
        facePos = model.G.cells.facePos(matrix_cells_right(kk)):model.G.cells.facePos(matrix_cells_right(kk)+1)-1;
        cfaces = model.G.cells.faces(facePos);
        Tid = facePos(find(cfaces==fdom.region(kk)));
        half_trans.matfrac_right(kk) = model.G.FracturedDomains.half_trans(Tid);
    end

    %% Assemble the frac-mat full transmissiblties            
    trans_left = half_trans.matfrac_left .* half_trans.fracmat./...
        (half_trans.matfrac_left + half_trans.fracmat);
    trans_right = half_trans.matfrac_right .* half_trans.fracmat./...

