                           'n',  [1, 1], ...
                           'rho', [1000, 700]*kilogram/meter^3);

% Initial state
lower = G.cells.centroids(:, 3) > 0.5*input.physDims(3);
sW = ones(G.cells.num, 1);
sW(lower) = 0;
