%% Example of connecting the well-region grid to Cartesian grid by the Voronoi grid
%
% This example demonstrates the use of Voronoi (pebi) grid to connect the 
% well-region (WR) grid to Cartesian grid. The Voronoi grid is constructed
% by the combination of 'voronoin' (provides grid nodes and connectivity
% list) and 'tessellationGrid', before which five special treatments are 
% conducted, i.e. 
% * Designing the generating points
% * Clipping the Voronoi diagram
% * Removing conflicting points
% * Connecting with the WR grid
% * Connecting with the Cartesian grid

clear
mrstModule add nwm upr ad-core ad-props ad-blackoil diagnostics

%% Build the Cartesian grid
GC = cartGrid([25, 25], [200, 200]);
GC = computeGeometry(GC);

%% Define well trajectory and region of interest (ROI) boundary
% The well trajectory, should be located inside the ROI boundary.
ns = 12;
th = linspace(0.85, 0.7, ns+1)' * pi;
traj = [150*cos(th)+200, 150*sin(th)];
% The polygonal ROI boundary
pbdy = [136, 150;
        145,  95;
         90,  30;
         35,  45;
         45, 105;
         90, 160];

% Get cells inside and outside the ROI
cCtro = GC.cells.centroids;
in = inpolygon(cCtro(:,1), cCtro(:,2), pbdy(:,1), pbdy(:,2));
cI = find( in );
cO = find(~in );

% Extract the sorted boundary nodes and boundary cells (in counterclockwise).
% The actual ROI boundary is aligned to the grid edges (faces) and 
% therefore lead the nonconvex polygons. So, we first sort the convex 
% polygon specified by the centroids of boundary edges, and then obtain the 
% sorted boundary nodes and cells from associated faces.
[bnC, bcC] = extractBdyNodesCells(GC, cI);

function [pIn, pOut, R] = demoComputeAuxPts(p, bn, m0)
% An excerpt from 'generateVOIGridNodes' to show how to generate the 
% auxiliary points for the Voronoi diagram. The auxiliary points help to
% locate the boundary nodes in p, i.e. p(bn, :).

    pib = p(bn, :);
    pib = [pib; pib(1,:)];
    n   = size(bn,1);
    e2n = [(1:n)', [(2:n)';1]];
    % Compute the radius
    edges = [bn, [bn(2:end); bn(1)]];
    L  = p(edges(:,1),:) - p(edges(:,2),:);
    L  = sqrt(sum(L.^2,2));
    do = true;
    m  = m0;
    while do
        if m > 0.5
            throwError(L)
        end
        try
            m = m + 0.02;
            R = ( [L(1);L(1:n-1)] + [L(n);L(2:n)] ) * m;
            [pIn, pOut] = deal( zeros(size(edges,1), 2) );
            for i = 1 : size(edges,1)
                [x1, y1, x2, y2] = deal(p(edges(i,1),1), p(edges(i,1),2), ...
                    p(edges(i,2),1), p(edges(i,2),2));
                [r1, r2] = deal(R(e2n(i,1)), R(e2n(i,2)));
                pCross = circleCross(x1, y1, r1, x2, y2, r2);
                in = inpolygon(pCross(:,1), pCross(:,2), pib(:,1), pib(:,2));
                pIn(i, :)   = pCross(in, :);
                pOut(i, :)  = pCross(~in, :);
            end
            do = false;
        catch
            do = true;
        end
    end

    figure, hold on, axis equal tight off
    demoPlotPoly(p(bn, :), 'ko-', 'y', 5)
    th = linspace(0, 2*pi, 100)';
    for i = 1 : size(edges,1)
        pCri = bsxfun(@plus, [R(i)*cos(th), R(i)*sin(th)], p(bn(i),:));
        demoPlotLine(pCri, 'r-', 'r', 1)
        demoPlotLine([pIn(i, :); pOut(i, :)], 'bs-', 'g', 5)

function [p, t, bdyID] = demoHandleVoronoiDiag(pVor, tVor, pib, pob, pW, tW, bnW)
% An excerpt from 'generateVOIGridNodes' to show how to handle the infinite
% Voronoi diagram. This includes (1) clip the Voronoi diagram, (2) remove
% the conflicting points, and (3) connect with the WR grid.

    % Clip the infinite Voronoi diagram: remove points outside the region
    fdI = @(p)dpoly(p, [pib; pib(1,:)]);
    fdO = @(p)dpoly(p, [pob; pob(1,:)]);
    fd  = @(p)ddiff(fdO(p), fdI(p));
    tol1 = 0.1;
    in  = find(fd(pVor) < tol1 & all(~isinf(pVor), 2));
    map = [(1:length(in))', in];
    pVor = pVor(map(:,2), :);

    % Remove conflict points (point too close to each other)
    D = euclideanDistance(pVor, pVor);
    D = triu(D);
    tol2 = 0.1;
    [removed, reserved] = find(D < tol2);
    ii = removed < reserved; 
    removed = removed(ii);
    reserved = reserved(ii);
    map(removed,1) = map(reserved,1);
    idx  = find(~ismember((1:size(pVor,1))', removed));
    pVor = pVor(idx, :);
    map(:,1) = arrayfun(@(x)find(x == idx), map(:,1));

    % Map the connectivity list
    tVor = cellfunUniOut(@(x)unique( map(ismember(map(:,2), x), 1)' ), tVor);
    tVor = tVor( cellfun(@length, tVor) > 3 );

    % Connect with the WR grid: add WR points, and map the connectivity 
    % list again
    D2 = euclideanDistance(pVor, pib);
    [IBID, ~] = find( bsxfun(@eq, D2, min(D2)) );
    map1 = find( ~ismember((1:size(pVor,1))', IBID) );
    pVor = pVor(map1, :);
    map1 = [(1:length(map1))', map1];
    map1(:,1) = map1(:,1) + size(pW,1);
    map2 = [bnW, IBID];
    tVor = cellfunUniOut(@(x)[map1(ismember(map1(:,2), x), 1)', ...
        map2(ismember(map2(:,2), x), 1)'], tVor);
    p = [pW; pVor];
    t = [tW; tVor];

