end

function p = circleCross(x1, y1, r1, x2, y2, r2)
% Compute intersction points of two circiles
    if y1 ~= y2
        d  = sqrt( (x1-x2)^2+(y1-y2)^2 );
        k2 = -(x1-x2)/(y1-y2);
        b2 = (r1^2-r2^2-x1^2+x2^2-y1^2+y2^2)/(2*(y2-y1));

        if abs(r2-r1) < d && d < r2+r1
            delta = -b2^2 + r2^2 + k2^2 *r2^2 - 2 *b2* k2* x2 - ...
                k2^2* x2^2 + 2*b2*y2 + 2*k2*x2*y2 - y2^2;
            xx1 = (-b2* k2 + x2 + k2 *y2 - sqrt(delta))/(1 + k2^2);
            yy1 = k2*xx1 + b2;
            xx2 = (-b2* k2 + x2 + k2 *y2 + sqrt(delta))/(1 + k2^2);
            yy2 = k2*xx2 + b2;
            p = [xx1,yy1; xx2,yy2];
        else
            p = nan(2,2);
        end
    else
        p0 = [x1, y1; x2, y2];
        R = [r1; r2];
        [~, idx] = sort(p0(:,1));
        p0 = p0(idx, :);
        R = R(idx);
        [x1, x2, y1, y2, r1, r2] = deal(p0(1,1), p0(2,1), p0(1,2), p0(2,2),...
            R(1), R(2));
        d = abs(x2-x1);
        delta = (-d+r1-r2)*(-d-r1+r2)*(-d+r1+r2)*(d+r1+r2);
        if delta > 0
            a = sqrt(delta) / d;
            dx = (d^2 - r2^2 + r1^2)/(2*d);
            p = [x1 + dx, y1+a/2; x1 + dx, y1-a/2];
        else
            p = nan(2,2);
        end
    end
end

function pmid = computeCentroids(p)
% Compute centroids of the 2D polygon specified by points p
    p0 = sum(p,1)/size(p,1);
    areas = zeros(size(p,1),1);
    pmids = zeros(size(p,1),2);
    p = [p; p(1,:)];
    for i = 1 : length(areas)
        pts = [p(i:i+1,:); p0];
        areas(i) = tri_area(pts(1,:), pts(2,:), pts(3,:));
        pmids(i,:) = sum(pts,1)/3;
    end
    pmid = [0, 0];
    pmid(1) = sum( pmids(:,1) .* areas ) / sum(areas);
    pmid(2) = sum( pmids(:,2) .* areas ) / sum(areas);
end

function f = computePD(x, y, a, b, xw, yw)
% Compute dimensionless pressure for the flow problem that a well is 
% arbitrarily located inside a rectangular box with width a and height b. 
% The distance from well to right boundary is xw and to the lower boundary 
% is yw
%       ------------------------------------------
%      |                               xw         |
%      |                 (Well) o ............... |
%      |                        .                 |
%      |                    yw  .                 |
%      |                        .                 |
%      |                        .                 |
%       -------------------------------------------

    % A constant for computing the infinite series
    N = 10; 
    nn = (-N : N)';
    p1 = pi/b * (x - 2*nn*a);
    p2 = pi/b * (x - 2*nn*a - 2*xw);

    q1 = pi/b *  y;
    q2 = pi/b * (y + 2*yw);
    s1 = cosh(p1) - cos(q2);
    s2 = cosh(p2) - cos(q1);
    s3 = cosh(p1) - cos(q1);
    s4 = cosh(p2) - cos(q2);

    f = log( (s1.*s2)./(s3.*s4) );
    f = sum(f);
end

