physdim = [1990 1990 150]*ft;

wellRadius = 0.25*ft;

matrixPoro = 0.16;
matrixPerm = 100*micro*darcy;

w_f = 0.01*ft;
k_f = 50*darcy;
x_f = 350*ft;


%% Create Box Reservoir Grid

[G_matrix,~,~]=explicitStencil3Fracs(physdim, 'aperture',w_f,...
