function [fracplanes,frac_centroid_s]=MulistagePlanarNonPlanarHF(varargin)
%{
Create multi-stage hydraulic fractures geometry
%This function can create Non planar fracture of any orientation

!Assume all fractures in a stage have the same half-length and height
!Assume each hydraulic fracture plane is a rectangl
Author: Harun Rashid % 
Date modified 12/26/2019
%}

opt = struct('numStages'        ,  0,                      ...
             'fracSpacing'    , [],                      ...
             'numFracsPerStage'    , [],                      ...
             'fracHalfLength'   , [],                      ...
             'fracHeight'       , [],                      ...
             'theta',[],...
             'clusterSpacing'      , [],                      ...             
             'heelCoord'        , [10.0 20.0 15.0]);
opt = merge_options(opt, varargin{:});


%Handle constant input
if(isscalar(opt.fracSpacing))
    opt.fracSpacing=repmat(opt.fracSpacing,1,opt.numStages-1);
end
if(isscalar(opt.numFracsPerStage))
    opt.numFracsPerStage=repmat(opt.numFracsPerStage,1,opt.numStages);
end
if(isscalar(opt.fracHalfLength))
    opt.fracHalfLength=repmat(opt.fracHalfLength,1,opt.numStages);
end
if(isscalar(opt.fracHeight))
    opt.fracHeight=repmat(opt.fracHeight,1,opt.numStages);
end
if(isscalar(opt.clusterSpacing))
    opt.clusterSpacing=repmat(opt.clusterSpacing,1,opt.numStages);
end


if numel(opt.fracHalfLength)~= opt.numStages
    disp('[Error] Incompatible Input array size of fracHalfLength against numStages!');
end

%Create struct of fracture planes

function G=StructuredGridFractureonFace(physdim,frac_centroid_s, varargin)
    %This will generate structured grid by putting hydraulic fractures on the grid faces
    %Author Harun Rashid
    opt = struct('aperture', 0.02,...
                 'numStages', [],...
                 'fracSpacing', 10,...
                 'fracHalfLength', 100,...
                 'fracHeight', 60,...
                 'nxRefine',10,...
                 'tipNY',5,...
                 'numFracsPerStage',[],...
                 'clusterSpacing',100,...
                 'ny',11, ...
                 'nxRefine_small',2,...
                 'nz',11 );

    opt = merge_options(opt, varargin{:});
    aa=frac_centroid_s(1)./opt.fracSpacing;
    bb=(physdim(1)-frac_centroid_s(end))./opt.fracSpacing;

    % This part will create grid from the left boundary to the first
    % fracture
    ptX = linspace(0, frac_centroid_s(1), aa*opt.nxRefine);
    wellCellcentroidX = frac_centroid_s(1);
    facesXcoords = wellCellcentroidX + -fliplr(ptX);
    i=1;
    n=1;
    for k=1:opt.numStages
        for j=1:opt.numFracsPerStage-1
            ptX1 = linspace(0, frac_centroid_s(n+j)-frac_centroid_s(n+j-1), opt.nxRefine_small);
            wellCellcentroidX=frac_centroid_s(n+j-1);
            facesXcoords1 = wellCellcentroidX + ptX1;
            facesXcoords=[facesXcoords, facesXcoords1];
        end
        if k <=opt.numStages-1
            ptX1 = linspace(0, frac_centroid_s(i+3)-frac_centroid_s(i+2), opt.nxRefine);
            wellCellcentroidX=frac_centroid_s(i+2);
            facesXcoords2 = wellCellcentroidX + ptX1;
            facesXcoords=[facesXcoords, facesXcoords2];
            i=i+3;
            n=n+3;
        end
    end
    % This part will create grid from the last fracture to the domain
    % boundary

