function schedule = HnP_schedule(inj, soak, prod,runtime, W)
%Make a schedule for HnP with user-specified durations for injection,
%soaking, and production
%
% SYNOPSIS:
%   schedule = simpleSchedule(timesteps);
%   schedule = simpleSchedule(timesteps, 'W', W, 'src', src, 'bc', bc);
%
% PARAMETERS:
%   
%   inj     - array of [injection period(day) timestep size(day) rampup counts].
%   soak    - array of [soaking period(day) timestep size(day) rampup counts].
%   prod    - array of [production period(day) timestep size(day) rampup counts].
%   W -  Wells to be used in the schedule. The wells will be active in
%        all timesteps. W is a struct with the following order: injector,
%        soaking, and producer.
%
% RETURNS:
%   schedule - struct suitable for HnP 

    dt_cycle= inj(1) + soak(1) + prod(1);
    cycle_count = floor(runtime/dt_cycle);

    schedule = struct();
    [W_inj, W_soak, W_prod] = deal(W);

    W_inj(2).status = false;
    W_soak(1).status = false; W_soak(2).status = false;
    W_prod(1).status = false;

    schedule.control = [struct('W', W_inj);...  % injection
                        struct('W', W_soak);     % soaking
                        struct('W', W_prod)];... % production
    dt = [];
    control_id = [];
    dt_inj = rampupTimesteps(inj(1), inj(2), inj(3));
    dt_inj = [dt_inj(1);dt_inj(1);dt_inj];

    dt_soak = rampupTimesteps(soak(1), soak(2), soak(3));
    dt_prod = rampupTimesteps(prod(1), prod(2), prod(3));
    for i = 1:cycle_count
        dt = [dt;dt_inj;dt_soak;dt_prod];
        control_id = [control_id;[2;2;ones(numel(dt_inj(3:end)),1)];2*ones(numel(dt_soak),1);3*ones(numel(dt_prod),1)];
%         control_id = [control_id;ones(numel(dt_inj),1);2*ones(numel(dt_soak),1);3*ones(numel(dt_prod),1)];
    end

function G=meshHFsystem(physdim,frac_centroid_s, varargin)
    %This will generate structured grid by putting hydraulic fractures on the grid faces
    %Author Harun Rashid
    opt = struct('aperture', 0.02,...
                 'numStages', [],...
                 'fracSpacing', 10,...
                 'fracHalfLength', 100,...
                 'fracHeight', 60,...
                 'nxRefine',10,...
                 'numFracsPerStage',[],...
                 'clusterSpacing',100,...
                 'ny',11, ...
                 'nxRefine_small',2,...
                 'nz',11 );

    opt = merge_options(opt, varargin{:});
    aa=frac_centroid_s(1)./(opt.fracSpacing/(opt.nxRefine-1));
    bb=(physdim(1)-frac_centroid_s(end))./(opt.fracSpacing/(opt.nxRefine-1));

    % This part will create grid from the left boundary to the first
    % fracture
    ptX = linspace(0, frac_centroid_s(1), aa);
    wellCellcentroidX = frac_centroid_s(1);
    facesXcoords = wellCellcentroidX + -fliplr(ptX);
    i=1;
    n=1;
    for k=1:opt.numStages
        for j=1:opt.numFracsPerStage-1
            ptX1 = linspace(0, frac_centroid_s(n+j)-frac_centroid_s(n+j-1), opt.nxRefine_small);
            wellCellcentroidX=frac_centroid_s(n+j-1);
            facesXcoords1 = wellCellcentroidX + ptX1;
            facesXcoords=[facesXcoords, facesXcoords1];
        end
        if k <=opt.numStages-1
            ptX1 = linspace(0, frac_centroid_s(i+opt.numFracsPerStage)-frac_centroid_s(i+opt.numFracsPerStage-1), opt.nxRefine);
            wellCellcentroidX=frac_centroid_s(i+opt.numFracsPerStage-1);
            facesXcoords2 = wellCellcentroidX + ptX1;
            facesXcoords=[facesXcoords, facesXcoords2];
            i=i+opt.numFracsPerStage;
            n=n+opt.numFracsPerStage;
        end
    end
    % This part will create grid from the last fracture to the domain
    % boundary
    ptX = linspace(0, physdim(1)-frac_centroid_s(end), bb);

