% In this example we demonstrate how to generate a continuous bivariate
% function (which can be regarded as a 2½D function) from a set of scattered
% sampled points, using the 'generate_trend_surface' function

%% making noisy, scattered sample points using the MATLAB logo function

% In order to generate a set of sampled points from an 'unknown' surface, we
% sample from a function readily available in MATLAB, namely the membrane
% function used in the MATLAB logo.

refsurf = membrane(1, 100);
refsurfarray = refsurf(:);

% sampling 1000 random points from the surface
num_pts = 1000;

x_ixs = ceil(rand([num_pts, 1]) * size(refsurf, 1));
y_ixs = ceil(rand([num_pts, 1]) * size(refsurf, 1));
z_val = refsurfarray(sub2ind(size(refsurf), x_ixs, y_ixs));

points = [x_ixs, y_ixs, z_val];

% We add some artificial noise, to pretend these points were obtained through
% some imprecise measurement process.  
zspan = max(z_val) - min(z_val);
noise_level = 0.02; % standard deviation 2% of full z span
noise = randn([num_pts, 1]) * noise_level * zspan;

noisy_points = points;
noisy_points(:,3) = points(:,3) + noise;

% plotting exact points (red) and noisy points (blue)
clf;
plot3(points(:,1), points(:,2), points(:,3), '.r'); hold on;
plot3(noisy_points(:,1), noisy_points(:,2), noisy_points(:,3), 'b.');
legend('Exact sample points', 'Noisy sample points')
set(gcf, 'position', [200 200 1000 640])

%% Generating "loose" surface from scattered points, using least squares

% The generated surface should not be forced to pass through the sample
% points, since the samples are noisy and we also care about regularity.

function p=bndproj(p,t,fd,varargin)
%BNDPROJ Project boundary points to true boundary
%   P=BNDPROJ(P,T,FD,FDARGS)

%   Copyright (C) 2004-2012 Per-Olof Persson. See COPYRIGHT.TXT for details.

deps=sqrt(eps)*max(max(p)-min(p));

if size(p,2)==2
  e=boundedges(p,t);
  e=unique(e(:));

  d=feval(fd,p(e,:),varargin{:});
  dgradx=(feval(fd,[p(e,1)+deps,p(e,2)],varargin{:})-d)/deps;
  dgrady=(feval(fd,[p(e,1),p(e,2)+deps],varargin{:})-d)/deps;
  dgrad2=dgradx.^2+dgrady.^2;
  dgrad2(dgrad2==0)=1;
  p(e,:)=p(e,:)-[d.*dgradx./dgrad2,d.*dgrady./dgrad2];
elseif size(p,2)==3
  if size(t,2)==3
    tri=t;
  else
    tri=surftri(p,t);
  end
  tri=unique(tri(:));

  d=feval(fd,p(tri,:),varargin{:});
  dgradx=(feval(fd,[p(tri,1)+deps,p(tri,2),p(tri,3)],varargin{:})-d)/deps;
  dgrady=(feval(fd,[p(tri,1),p(tri,2)+deps,p(tri,3)],varargin{:})-d)/deps;
  dgradz=(feval(fd,[p(tri,1),p(tri,2),p(tri,3)+deps],varargin{:})-d)/deps;
  dgrad2=dgradx.^2+dgrady.^2+dgradz.^2;
  dgrad2(dgrad2==0)=1;
  p(tri,:)=p(tri,:)-[d.*dgradx./dgrad2,d.*dgrady./dgrad2,d.*dgradz./dgrad2];
end

function e=boundedges(p,t)
%BOUNDEDGES Find boundary edges from triangular mesh
%   E=BOUNDEDGES(P,T)

%   Copyright (C) 2004-2012 Per-Olof Persson. See COPYRIGHT.TXT for details.

% Form all edges, non-duplicates are boundary edges
edges=[t(:,[1,2]);
       t(:,[1,3]);
       t(:,[2,3])];
node3=[t(:,3);t(:,2);t(:,1)];
edges=sort(edges,2);
[foo,ix,jx]=unique(edges,'rows');
vec=histc(jx,1:max(jx));
qx=find(vec==1);
e=edges(ix(qx),:);
node3=node3(ix(qx));

% Orientation
v1=p(e(:,2),:)-p(e(:,1),:);
v2=p(node3,:)-p(e(:,1),:);
ix=find(v1(:,1).*v2(:,2)-v1(:,2).*v2(:,1)>0);
e(ix,[1,2])=e(ix,[2,1]);

function [pc,r]=circumcenter(p,t)

%   Copyright (C) 2004-2012 Per-Olof Persson. See COPYRIGHT.TXT for details.

nt=size(t,1);
pc=zeros(nt,2);
r=zeros(nt,1);

for it=1:nt
  ct=t(it,:);
  dp1=p(ct(2),:)-p(ct(1),:);
  dp2=p(ct(3),:)-p(ct(1),:);

  mid1=(p(ct(2),:)+p(ct(1),:))/2;
  mid2=(p(ct(3),:)+p(ct(1),:))/2;

  s=[-dp1(2),dp2(2);dp1(1),-dp2(1)]\[-mid1+mid2]';

  cpc=mid1+s(1)*[-dp1(2),dp1(1)];
  cr=norm(p(ct(1),:)-cpc);

  pc(it,:)=cpc;
  r(it,1)=cr;
end

function d=dblock(p,x1,x2,y1,y2,z1,z2)

%   Copyright (C) 2004-2012 Per-Olof Persson. See COPYRIGHT.TXT for details.

d=-min(min(min(min(min(-z1+p(:,3),z2-p(:,3)),-y1+p(:,2)),y2-p(:,2)),-x1+p(:,1)),x2-p(:,1));

function d=dcircle(p,xc,yc,r)

%   Copyright (C) 2004-2012 Per-Olof Persson. See COPYRIGHT.TXT for details.

d=sqrt((p(:,1)-xc).^2+(p(:,2)-yc).^2)-r;

function d=dexpr(p,fin,nit,alpha)

%   Copyright (C) 2004-2012 Per-Olof Persson. See COPYRIGHT.TXT for details.

if nargin<3, nit=20; end
if nargin<4, alpha=0.1; end

fx=inline(vectorize(maple(['diff(',fin,',x)'])),'x','y');
fy=inline(vectorize(maple(['diff(',fin,',y)'])),'x','y');
fxx=inline(vectorize(maple(['diff(',fin,',x$2)'])),'x','y');
fyy=inline(vectorize(maple(['diff(',fin,',y$2)'])),'x','y');
fxy=inline(vectorize(maple(['diff(diff(',fin,',x),y)'])),'x','y');
f=inline(vectorize(fin),'x','y');

x0=p(:,1);
y0=p(:,2);
x=x0;
y=y0;
for it=1:nit
  cf=feval(f,x,y);
  cfx=feval(fx,x,y);
  cfy=feval(fy,x,y);
  cfxx=feval(fxx,x,y);
  cfxy=feval(fxy,x,y);
  cfyy=feval(fyy,x,y);

  F1=cf;
  F2=(x-x0).*cfy-(y-y0).*cfx;
  J11=cfx;
  J12=cfy;
  J21=cfy+(x-x0).*cfxy-(y-y0).*cfxx;
  J22=-cfx-(y-y0).*cfxy+(x-x0).*cfyy;

  detJ=J11.*J22-J12.*J21;
  detJ(detJ==0)=inf;

  x=x-alpha*(J22.*F1-J21.*F2)./detJ;
  y=y-alpha*(-J12.*F1+J11.*F2)./detJ;
end

d=sqrt((x-x0).^2+(y-y0).^2).*sign(feval(f,x0,y0));

