%% Example
% This script contains an example of a single curved well path intersected
% by several straight faults. We use the two wrapper-functions
% compositePebiGrid2D(..) and pebiGrid2D(..) to create PEBI grids conforming
% to the faults and the well path. In this example we will show how the
% wells can be traced by cell centroids of the PEBI grid and faults by
% faces of the grid.

%{
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Copyright (C) 2015-2020 Runar Lie Berge. See COPYRIGHT.TXT for details.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%}  

%% Set well and fault paths
% Store well and fault paths two cell arrays, in which each cell represents
% a single fracture or well paths. These are in turn given as arrays of
% of points that describe continuous line segments.

% We start by creating a well
x     = linspace(0.1, 0.8, 10);
y     = 0.2 + x.^2;
well  = {[x' , y']};

% And four faults crossing the well.
fault   = {[0.3,0.1;0.1,0.3],...        
          [0.3,0.1;0.4,0.7],...
          [0.6,0.2;0.3,0.7],...
          [0.8,0.4;0.5,0.8]};

% We now plot the well and fault to see how they look like
clf,set(gcf,'Position',[480 340 980 420]);
subplot(1,2,1), ax=gca;
patch([0 1 1 0],[0 0 1 1],ones(4,1),'FaceColor',[.95 .95 1]);
hold all
plotLinePath(well,'-o', 'LineWidth',2,'MarkerSize',3);
plotLinePath(fault,'-o','LineWidth',2,'MarkerSize',3);
title('Well path and fractures')
axis equal tight, axis ([0,1,0,1])
%subplot(1,2,2), copyobj(get(ax,'Children'),gca);

%% Construct Voronoi grid using compositePebiGrid2D
% Before we call the gridding fuctions we set some parameters.
gS  = 1/24; % The grid size
wGf = 0.5;  % The relative size of well cells compared to gS

%% Example
% In this example we show all optional options for compositePebiGrid2D.

%{
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Copyright (C) 2016-2020 Runar Lie Berge. See COPYRIGHT.TXT for details.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%}

%% cellConstraints
% This sets the cell constraints in our reservoir. The desired feature of
% these constraints is that the cell centroids of the grid cell trace the
% lines that define the constraints. In practice, we can not guarantee that
% the cell centroids trace the given constraints, instead, the algorithm
% will place the PEBI sites along the constrained lines. However, if the
% grid is fairly "nice", the cell centroids will align with the PEBI sites.
% The cell contstraints are stored as a cell array, each element
% corresponding to one line:
w = {[0.2,0.8;0.5,0.6;0.8,0.8],...
     [0.5,0.2]};
gS = [0.1,0.1];
pdims=[1,1];
G = compositePebiGrid2D(gS, pdims,'cellConstraints',w);

clf
plotGrid(G);
plotGrid(G,G.cells.tag,'facecolor','b')
axis equal tight off
plotLinePath(w,'wo-','linewidth',2,'MarkerFaceColor','w');


%% CCFactor
% The CCFactor sets the relative distance between the sites that trace the
% cellConstraints. If CCFactor=0.5 the distance between the cellConstraint
% sites will be about half the size of the reservoir grid size:
w = {[0.2,0.3;0.8,0.7]};
gS = [0.1,0.1];
pdims=[1,1];
G1 = compositePebiGrid2D(gS, pdims,'cellConstraints',w,'CCFactor',1);
G2 = compositePebiGrid2D(gS, pdims,'cellConstraints',w,'CCFactor',1/2);

figure('Position',[480 340 980 420])
