function [newPoints, dt] = eqInterpret(path, dt,sePtn)
% Interpolate a path with equiv distant points
% Arguments:
%   path       n*2 array of coordinates of points which are to be
%              interpolated
%   dt         distance between interpolation points
%
% Return:
%   newPoints  The interpolated points
%   dt         distance between the interpolated points

%{
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Copyright (C) 2016 Runar Lie Berge. See COPYRIGHT.TXT for details.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%}

linesDist = sqrt(sum(diff(path,[],1).^2,2));
linesDist = [0; linesDist]; % add the starting point
cumDist = cumsum(linesDist);
s = dt*sePtn(1); e = dt*sePtn(2);
dt = (cumDist(end)-s-e)/ceil((cumDist(end)-s-e)/dt);
newPointsLoc = s:dt:cumDist(end) - e;

newPoints = interp1(cumDist, path, newPointsLoc);    
end

function inside = inPolygon(poly, ptn)
    tol = 1e-6;
    poly = poly - ptn;
    ind = [1:size(poly,1), 1];
    prev_side = 0;
    for e = 1:numel(ind) - 1
        v1 = poly(ind(e), :);
        v2 = poly(ind(e + 1), :);
        v1Xv2 = v2(1)*v1(2) - v1(1)*v2(2);
        current_side = sign(v1Xv2);
        if abs(v1Xv2) <= tol
            inside = false;
            return
        elseif prev_side == 0
            prev_side = current_side;
        elseif prev_side ~= current_side
            inside = false;
            return
        end
    end
    inside = true;
end

function [X,Y, segInt] = lineLineInt(L1, L2)
% Calculates the intersections of line segments L1 with line segments L2
% Copyright (C) 2016 Runar Lie Berge. See COPYRIGHT.TXT for details.
TOL = 1000 * (max(L1(:)) - min(L1(:))) * eps;
numL2 = size(L2,1);
numL1 = size(L1,1);
L1    = repmat(L1,  1 ,numL2);
L2    = repmat(L2', numL1, 1); 

L1x1  = L1(:,1:4:end);
L1x2  = L1(:,3:4:end);
L1y1  = L1(:,2:4:end);
L1y2  = L1(:,4:4:end);

L2x1  = L2(1:4:end,:);
L2x2  = L2(3:4:end,:);
L2y1  = L2(2:4:end,:);
L2y2  = L2(4:4:end,:);

A1    = L1y2 - L1y1;
B1    = L1x1 - L1x2;
C1    = A1.*L1x1 + B1.*L1y1;
A2    = L2y2 - L2y1;
B2    = L2x1 - L2x2;
C2    = A2.*L2x1 + B2.*L2y1;

det   = A1.*B2 - A2.*B1;

X     = (B2.*C1 - B1.*C2)./det;
Y     = (A1.*C2 - A2.*C1)./det;

segInt = min(L1x1, L1x2) - X<=TOL & X - max(L1x1, L1x2)<=TOL ...
       & min(L2x1, L2x2) - X<=TOL & X - max(L2x1, L2x2)<=TOL ...
       & min(L1y1, L1y2) - Y<=TOL & Y - max(L1y1, L1y2)<=TOL ...
       & min(L2y1, L2y2) - Y<=TOL & Y - max(L2y1, L2y2)<=TOL;
end

function normal = normalFromPoints(p)
    assert(size(p,1)>=3)
    p1 = p(1, :);
    p2 = p(2,:);
    p_mean = mean(p, 1);
    v1 = p2 - p1;
    v2 = p_mean - p1;

    normal = cross(v1, v2);
    if sum(abs(normal))<1e-8
        normal = normalFromPoints(p(:, 2:end));
        return
    end
    normal = normal / sqrt(sum(normal.^2));
end

function d = pdist(x)
  % Equivalent to the matlab function pdist
  % Arguments:
  %    x         A set of points [x,y]
  % Returns:
  %    d         Distance, all to all
  % Halvor Møll Nielsen
    nc=size(x,1);
    d=zeros(1,nc*(nc-1)/2);
    nf=0;

    for i=1:nc-1
        dl=sqrt(sum(bsxfun(@minus,x(i,:),x(i+1:end,:)).^2,2));
        ndl=numel(dl);
        d(nf+1:nf+ndl)=dl;
        nf=nf+ndl;
    end
end

function I = polygonInt_v2(G,cells,f,k)
% This code is written by Oeystein Klemetsdal:
% �ystein Strengehagen Klemetsdal,
% The virtual element method as a common framework for finite element
% and finite difference methods - Numerical and theoretical analysis,
% June 2016,
% Masters thesis,
% Department of Mathematics,
% Norwegian University of Science and Technology.
% git@bitbucket.org:strene/the-virtual-element-method.git
[Xq, w, V, vol] = triangleQuadRule(k);

nq = size(Xq,1);

nK = numel(cells);

I = zeros(nK,size(f([0,0],1),2));

for i = 1:nK

    nodeNum = G.cells.nodePos(cells(i)):G.cells.nodePos(cells(i)+1)-1;
    nodes = G.cells.nodes(nodeNum);

    X = G.nodes.coords(nodes,:);
    tri = delaunay(X);
    nTri = size(tri,1);

                            %   Construct map from polygon to local face
                            %   coordinates.
    bA = X(tri(:,1),:);
    A = X(tri(:,2:end),:) - repmat(bA,2,1);
    A = A(mcolon(1:nTri,2*nTri,nTri),:);
    A = mat2cell(A,2*ones(nTri,1),2);
    D = cellfun(@(X) abs(det(X)), A);

    Xhat = cell2mat(cellfun(@(X) Xq*X, A, 'uniformOutput', false));
    Xhat = Xhat + rldecode(bA,nq*ones(nTri,1),1);
    I(i,:) = vol*repmat(w,1,nTri).*(rldecode(D,nq*ones(nTri,1),1))'*f(Xhat,i);

end

end

function int = polygonIntersection(poly_1, poly_2)
    tol = 1e-6;
    center_1 = mean(poly_1, 1);
    poly_1 = bsxfun(@minus, poly_1, center_1);
    poly_2 = bsxfun(@minus, poly_2, center_1);
    R = rotationMatrixFromPlane(poly_1);
    poly_1 = poly_1 * R';
    assert(sum(abs(poly_1(:, 3)))<1e-6);
    poly_1 = poly_1(:,1:2);
    poly_2 = poly_2 * R';

    if all(poly_2(:, 3) > tol) || all(poly_2(:, 3) < -tol)
        int = zeros(0, 3);
        return
    elseif all(abs(poly_2(:, 3)) < tol)
        % We do not treat parallel polygons. Hope for the best
        int = zeros(0, 3);
        return
    end
    ind = [1:size(poly_2,1), 1];
    AB = [];
    % Calculate the intersection of each line segment and the plane
    for e = 1:numel(ind) - 1
        v1 = poly_2(ind(e),:);
        v2 = poly_2(ind(e + 1),:);
        I = edge_intersecting_plane([0,0,1], [0,0,0], v1, v2);
        if size(I, 1)==0
            continue
        end
        AB = [AB; I];
    end
    % If a polygon node lies exactly at the plane both edges connected to
    % the node will create an intersection. Remove duplicates
    AB = round(AB * 1e10)/1e10;
    AB = unique(AB, 'rows');
    % The if statement above ensures that the polygon crosses the plane.
    % Our convex polygon should therefore have exactly two intersections
    % with this plane.
    assert(size(AB,1)==2)
    assert(all(abs(AB(:,3))<tol))
    AB = AB(:, 1:2);

    % Now test if the two intersections are innside the first polygon
    A_innside = inPolygon(poly_1, AB(1,:));
    B_innside = inPolygon(poly_1, AB(2,:));

function [H] = rodriguesRotation(G, phi, u, x0)
    W = [0,   -u(3),  u(2);
         u(3),    0, -u(1);
        -u(2), u(1),     0];
    R = eye(3) + sin(phi) * W + (2 * sin(phi / 2)^2) * W^2;
    H = G;
    for i = 1:G.nodes.num
        H.nodes.coords(i, :) = (R * (G.nodes.coords(i, :)' - x0'))' + x0;
    end
end

function mat = rotationMatrixFromPlane(poly)
    normal = normalFromPoints(poly);
    z_basis = [0,0,1];
    theta = acos(dot(normal, z_basis));
    v = cross(normal, z_basis);
    if sum(abs(v))<1e-8
        mat = eye(3);
        return
    end
    v = v/sqrt(sum(v.^2));
    mat_x = [     0, -v(3),  v(2);...
               v(3),     0, -v(1);...
              -v(2),  v(1),     0];
   mat_t = [v(1)^2, v(1)*v(2), v(1)*v(3); ...
            v(1)*v(2), v(2)^2, v(2)*v(3); ...
            v(1)*v(3), v(2)*v(3), v(3)^3];
   mat = cos(theta) * eye(3) + sin(theta) * mat_x + (1-cos(theta))*mat_t;
end

function mat = rotationMatrixFromVector(theta, vec)
    if sum(abs(vec))<1e-8
        mat = eye(3);
        return
    end
    v = vec/sqrt(sum(vec.^2));
    mat_x = [     0, -v(3),  v(2);...
               v(3),     0, -v(1);...
              -v(2),  v(1),     0];
   mat_t = [v(1)^2, v(1)*v(2), v(1)*v(3); ...
            v(1)*v(2), v(2)^2, v(2)*v(3); ...
            v(1)*v(3), v(2)*v(3), v(3)^3];
   mat = cos(theta) * eye(3) + sin(theta) * mat_x + (1-cos(theta))*mat_t;
end

