function D = formReconstructionMatrixLocal(A, partition, centers)
    N = size(A, 1);
    [i, j, d] = find(A);
    isCenter = false(N, 1);
    isCenter(centers) = true;

    fix = isCenter(i) & isCenter(j);
    d(fix) = 2*d(fix);

    pi = partition(i);
    pj = partition(j);

