%% Problem comparing different multiscale methods on an idealized channel
% Extensive numerical experiments have shown that contemporary multiscale
% methods provide approximate solutions of good quality for highly
% heterogeneous media. However, cases with large permeability contrasts are
% generally challenging and it is not difficult to construct pathological
% test cases on which a particular method fails to produce accurate
% solutions. Diagonal channel. Kippe et al. proposed a simple and
% illuminating example consisting of a narrow high-permeable channel in a
% low-permeable background, where the channel is aligned with the diagonal
% direction. 
%
% This example corresponds to Example 4.3.3 in
%  A multiscale restriction-smoothed basis method for high contrast porous
%  media represented on unstructured grids. J. Comput. Phys, Vol. 304, pp.
%  46-71, 2016. DOI: 10.1016/j.jcp.2015.10.010

% Load modules
mrstModule add msrsb incomp coarsegrid mrst-gui msfvm matlab_bgl

%% We set up the domain
% The domain consists of 65 by 65 fine cells and a permeability field that
% is equal to 10 mD everywhere except for a narrow channel that crosses the
% domain diagonally, where the permeability is 1000 mD.

dims = [65, 65];
pdims = [1000 1000]*meter;
G = cartGrid(dims, pdims);
G = computeGeometry(G);

% Alternate intersection can be inserted. This channel crosses the blocks
% diagonally and is not a problem for either finite-volume multiscale
% scheme.
% x1 = repmat([0, 0, 0], G.cells.num, 1);
% x2 = repmat([1, 1, 0], G.cells.num, 1);
x1 = repmat([0.0, 0.05, 0], G.cells.num, 1);
x2 = repmat([0.95, 1.0, 0], G.cells.num, 1);

% Insert channel based on distance
x0 = [bsxfun(@rdivide, G.cells.centroids, pdims), zeros(G.cells.num, 1)];
dist = sqrt(sum(cross(x2 - x1, x1 - x0).^2, 2)./sum((x2 - x1).^2, 2));
isChannel = dist < 0.02;
% Set up rock structure
perm = repmat(10*milli*darcy, G.cells.num, 1);
perm(isChannel) = 1*darcy;
rock = makeRock(G, perm, 1);

%% Multiscale solver with inactive cells / inclusions
% A tough test case for any multiscale solver is a grid with many inactive
% cells that make coarse grids highly challenging. This example
% demonstrates the robustness of MsRSB when faced with a large number of
% inactive cells.
%
% This example corresponds to Example 4.3.5 in
%  A multiscale restriction-smoothed basis method for high contrast porous
%  media represented on unstructured grids. J. Comput. Phys, Vol. 304, pp.
%  46-71, 2016. DOI: 10.1016/j.jcp.2015.10.010

mrstModule add  msrsb coarsegrid mrst-gui incomp

%%  Grid and petrophysics
% We have stored a image containing the inclusions
img = imread(fullfile(mrstPath('msrsb'), 'examples', 'inclusions.png'));
img = double(img(:,:,1));

dims = size(img);
pdims = [1 1]*kilo*meter;
G = cartGrid(dims, pdims);
active = find(img == 255);

% Extract active cells
G = extractSubgrid(G, active);
G = computeGeometry(G);

% Create a simple log-normal permeability field and map onto active subset
k = logNormLayers(G.cartDims);
perm = k(G.cells.indexMap)*darcy;
poro = 0.5;
rock = makeRock(G, perm, poro);
T = computeTrans(G, rock);

clf,
plotCellData(G,log10(rock.perm),'EdgeColor','none')

% Single-phase unit fluid model. Since we are solving a single-phase
% incompressible problem without gravity, the values here do not matter.
fluid = initSimpleFluid('rho', [1, 1], 'mu', [1, 1], 'n', [1 1]);

%% Solve fine-scale problem
% We inject one pore volume over ten years with wells in opposing corners.
time = 10*year;
Nt = 100;

%% Introduction to the use of multiscale solvers as an iterative two-level method
% This example demonstrates the use of multiscale solvers as two-level
% multigrid-like methods. We demonstrate several different interfaces for
% iterative multiscale methods in MRST, depending on the intended usage. We
% recommend that you first go through the introMultiscale example before
% running this example, as we here do not detail the basic interfaces.
mrstModule add coarsegrid spe10 msrsb incomp ad-core

%% Define grid and rock
dims = [30, 110];
physDims = dims .*[20, 10]*ft;
% Create grid
G = cartGrid(dims, physDims);
G = computeGeometry(G);
n = G.cells.num;

% Take the rock structure from layer 15
rock = getSPE10rock(1:dims(1), 1:dims(2), 15);
rock.perm = rock.perm(:, 1);
rock.poro = max(rock.poro, 1e-3);
hT = computeTrans(G, rock);
% Coarsen into uniform grid
cdims = ceil(dims./[5, 10]);
p = partitionUI(G, cdims);
% Make coarse grid
CG = generateCoarseGrid(G, p);
% Add coarse geometry (centroids, normals, etc)
CG = coarsenGeometry(CG);
CG = storeInteractionRegion(CG);

%% Set up a problem with two wells
% We here set up a problem where wells are the driving force. Wells are
% the most common driving forces for field-scale simulation, and can be
% challenging to resolve as they represent a highly localized source terms.
% Here, the wells are simple point-wells in the first and last cell of the
% domain, corresponding to each corner of a structured grid.
W = [];
W = addWell(W, G, rock, 1, 'type', 'bhp', 'val', 100*barsa);
W = addWell(W, G, rock, n, 'type', 'bhp', 'val', 50*barsa);
fluid = initSingleFluid('rho', 1, 'mu', 1);
state0 = initResSol(G, 0);
% Call fine-scale solver, with matrix output in state enabled
state = incompTPFA(state0, G, hT, fluid, 'MatrixOutput', true, 'W', W);

%% Get the linear system from the report

%% Water injection in a field model using the MsRSB-method
% This example demonstrates the use of the MsRSB method to a synthethic
% waterflood on the grid and petrophysical properties from a real field. 
%
% This example is a modified version of Example 4.3.6 in
%  A multiscale restriction-smoothed basis method for high contrast porous
%  media represented on unstructured grids. J. Comput. Phys, Vol. 304, pp.
%  46-71, 2016. DOI: 10.1016/j.jcp.2015.10.010
%
% Note that this example uses MEX-accelerated computation of basis functions
% which requires that MEX is set up and configured to work with an
% installed C++ compiler on your machine.

mrstModule add coarsegrid msrsb ad-core mrst-gui incomp

%% Read and set up the Norne model
% We use a subset of the Norne model that is used in other examples in
% MRST. We set up a model with anisotropic permeability based on the
% vertical permeability.
mrstModule add deckformat

grdecl = fullfile(getDatasetPath('norne'), 'NORNE.GRDECL');
grdecl = readGRDECL(grdecl);
usys   = getUnitSystem('METRIC');
grdecl = convertInputUnits(grdecl, usys);

G = processGRDECL(grdecl, 'PreserveCpNodes', true);
G = computeGeometry(G(1));
rock = grdecl2Rock(grdecl, G.cells.indexMap);

% Backwards compatible plotting
if isnumeric(gcf)
    myZoom = @zoom;
else
    myZoom = @(varargin) [];
end
%% Plot permeability and porosity
figure;
plotCellData(G, log10(rock.perm(:, 1)));
axis equal tight off
daspect([1 1 0.2])
view(85, 45); myZoom(1.2);
colorbar
title('Horizontal permeability (log10)')

%% Simulate a transport problem with the MsRSB method
% This example is a simple demonstration in how to use the multiscale
% solver to solve a transport problem using the incomp module.

mrstModule add mrst-gui spe10 coarsegrid incomp


%%  Set up the fine-scale model
% We set up a layer of SPE10, just as in the introductory single-phase
% <matlab:edit('exampleMs.m') exampleMs> example.

% Grid an petrophysics
layerNo = 85;
[G, ~, rock] = getSPE10setup(layerNo);
mp = 0.01;
rock.poro(rock.poro < mp) = mp;

% Transmissibilities on fine scale
T = computeTrans(G, rock);

% Inject 1 PV over 10 years
time = 10*year;
Nt = 100;
pv = poreVolume(G, rock);

% Set up wells in each corner
injr = sum(pv)/(time);
W = [];
W = verticalWell(W, G, rock, 1, 1, [], 'type', 'rate', ...
    'val', injr, 'comp_i', [1, 0]);
W = verticalWell(W, G, rock, G.cartDims(1), G.cartDims(2), [],...
    'type', 'bhp' , 'val', 100*barsa, 'comp_i', [1, 0]);

% Plot the permeability field (log-scale).
figure(1); clf
plotToolbar(G, log10(rock.perm(:, 1)));
axis equal tight off
colormap jet
view(90, 90);

