function pick = findClosestCell(g,x,y,sub)
% Find the cell with center closest to the point (x,y)
%
% SYNOPSIS
% pick = findClosestCell(g,x,y,sub)
%
% PARAMETERS
%       g - mrst grid structure
%       x,y - x and y coordinates
%
%       OPTIONAL
%       sub - a subset of the cells to search within
%
% Copyright 2011-2012 University of Bergen, 2013 IRIS AS
%
% This file is licensed under the GNU General Public License v3.0.

% search among all cells if no restriction are given
if nargin <4
    sub = 1:g.cells.num;
end

% pick out the centroids
xc = g.cells.centroids(sub,1);
yc = g.cells.centroids(sub,2);

% find the closest cell, one point at the time
pick = zeros(numel(x),1);
for i = 1:numel(x)
    d = sqrt((xc - x(i)).^2 + (yc - y(i)).^2);

    [~,ind] = min(d);
    if nargin == 4
        if numel(sub)==g.cells.num
            sub = find(sub);
        end
        ind = sub(ind);
    end
    pick(i) = ind;
end

function makeCartFrac(n,ftag,box,filename)
% saves a Cartesian grid in filename
%
% SYNOPSIS
%  makeCartFrac(n,ftag,box,filename)
%
% PARAMETERS
% n:    a matrix containing the number of internal points for each set of
%       Cartesian grid i.e. different tags can be used for the different
%       sets
% ftag: tag numbers must have the size of the rows of n.
% box:  bounding box
% filename: file name where the vertices and edges are stored
%
% Copyright 2013 IRIS AS
%
% This file is licensed under the GNU General Public License v3.0.



% number of internal points for each set
numf = sum(n,1);

% find the endpoints of the sets
x = [];
y = [];
tags = [];

for i = 1 : numel(ftag)
    x_tmp = linspace(box(1,1),box(2,1),n(i,1)+2)';
    x_tmp = x_tmp(2:n(i,1)+1);
    y_tmp = linspace(box(1,2),box(2,2),n(i,2)+2)';
    y_tmp = y_tmp(2:n(i,2)+1);
    tags_tmp = ftag(i)*ones(n(i),1);
    x = [x ; x_tmp];
    y = [y ; y_tmp];
    tags = [tags ; tags_tmp];
end

% compute vertices and edges
vertices = [rldecode(x,2),repmat([box(1,2);box(2,2)],numf(1),1);  ...
    repmat([box(1,1);box(2,1)],numf(2),1),rldecode(y,2)];
edges = reshape((1:sum(numf)*2)',2,[])';
tags = repmat(tags,2,1);
edges = [edges,tags];

function [g,remove_faces] = mergeCells(g,remove_faces)
% merge two cells separated by the first face in remove_faces
% return the updated remove_faces list as well as a grid
% with one less number of cells.
%
% SYNOPSIS
%     [g,remove_faces] = mergeCells(g,remove_faces)
%
% PARAMETERS
%       g - mrst grid structure
%       remove_faces - a list of faces to be removed
%                       NB Only the first face is removed
%
% OUTPUT
%       g - mrst grid structure with one less cell
%       remove-faces - updated list of faces (- the removed faces)
%
% Copyright 2011-2012 University of Bergen, 2013 IRIS AS
%
% This file is licensed under the GNU General Public License v3.0.

% picks the face to be merged.
ind = false(g.faces.num,1);

% we merge two cells at the time starting at the first face in remove_faces
ind(remove_faces(1)) = true;

% the associated cells
cells = g.faces.neighbors(ind,:);
cells = unique(cells)';

% store the face and nodes before removing the cells in
% order to reconstruct the new cell
faceind = rldecode(1:g.cells.num,diff(g.cells.facePos),2)';
nodeind = rldecode(1:g.cells.num,diff(g.cells.nodePos),2)';
faces =  g.cells.faces;
nodes = unique(g.cells.nodes(ismember(nodeind,cells),:));
n = g.faces.neighbors;

% remove the old cells
[g, cellmap, facemap, nodemap] = removeCells_mod(g, cells,ind);

n = n(facemap>0,:);
cellmap(cellmap==0) = g.cells.num+1;
g.faces.neighbors(n(:,1)>0,1) = cellmap(n(n(:,1)>0,1));

function [vertices,edges] = removeDuplicates(vertices,edges)
% Remove duplicated edges and vertices
% The first tag is kept
% TODO: keep track of the lost tags
%
% SYNAPSES
% [vertices,edges] = removeDuplicates(vertices,edges)
%
% PARAMETERS
%       vertices - original vertices list
%       edges - original edge list
%
% OUTPUT
%       vertices - vertices list without duplicates
%       edges - edge list without duplicates
%
% Copyright 2011-2012 University of Bergen, 2013 IRIS AS
%
% This file is licensed under the GNU General Public License v3.0.

% take care of the tags
tags = edges(:,3:end);

% remove tags
edges = edges(:,1:2);

% remove duplicated nodes
[vertices,~,J] = unique(vertices,'rows','first');
edges(:,1:2) = J(edges(:,1:2));

% remove duplicated edges
[~,I] = unique(sort(edges,2),'rows','first');
edges = edges(I,:);

% keep the first tag
tags = tags(I,:);

% remove edges going nowhere
keep = edges(:,1)~=edges(:,2);
edges = edges(keep,:);
tags = tags(keep,:);

% add back the tags
edges = [edges,tags];

function [vertices, new_edges, map] = ...
                        partition_edges(vertices, old_edges, space, box, opts)
% [vertices, new_edges, num_added] = ...
%                      partition_edges (vertices, old_edges, space, box, opts)
%
% Make sure that no edges are longer than the give size. If an edge is
% longer, it is split up into subsegments which are then joined together.
% map is a m-by-2 array which contains in the first column the index of the
% vertex added and in the second column the index of a line to which it is
% constrained.
%
% Portions Copyright (C) 2006-2007 Uni Research AS
% This file is licensed under the GNU General Public License v3.0.

   new_edges = [];
   map = [];

   % do for each edge in the edge set
   for i = 1:size (old_edges, 1)
      % get the coordinates of each endpoint of the line
      x_a = vertices(old_edges(i, 1), 1);
      y_a = vertices(old_edges(i, 1), 2);
      x_b = vertices(old_edges(i, 2), 1);
      y_b = vertices(old_edges(i, 2), 2);

      % each partition is going to be of the same type as the main edge
      c = old_edges(i, 3:end);

      % figure out the number of points we'll need in addition to the
      % starting point (the endpoint counts, so there should always be at
      % least one) to describe this line in terms of smaller segments with
      % at most 'space' length
      total_length = sqrt ((x_b - x_a)^2 + (y_b - y_a)^2);
      num_points = ceil (total_length / space);

      % parameterize the line so that it is described according to a
      % counter going from 0 to num_points:
      %     x = t/n * (x_b - x_a) + x_a
      %     y = t/n * (y_b - y_a) + y_a
      dx = (x_b - x_a) / num_points;
      dy = (y_b - y_a) / num_points;

      % start out at the first point of the old line
      last_point = old_edges(i, 1);

