function nodes=arrangenodes(nodes,normal,varargin)

opt=struct('numvertices',0);
opt=merge_options(opt,varargin{:});

if opt.numvertices==0
    numvertices=size(nodes,1);
else
    numvertices=opt.numvertices;
end

dirx=nodes(2,:)-nodes(1,:);
dirx=dirx/norm(dirx); % make unit
diry=cross(normal,dirx);

center=sum(nodes)/numvertices;
relposition=nodes-repmat(center,numvertices,1);
xpos=dot(relposition,repmat(dirx,numvertices,1),2);
ypos=dot(relposition,repmat(diry,numvertices,1),2);

angle=zeros(numvertices,1);

for i=1:numvertices
    if xpos(i)>=0 && ypos(i)>=0  % quadrant 1
        angle(i)=atan(ypos(i)/xpos(i));
    elseif xpos(i)>=0 && ypos(i)<=0 % quadrant 4
        angle(i)=2*pi+atan(ypos(i)/xpos(i));
    else % quadrant 2&3
        angle(i)=pi+atan(ypos(i)/xpos(i));
    end % there shouldn't be a case of xpos(i)==0 since we use the center as reference. Division by 0 won't happen.
end

[~,index]=sort(angle);

nodes=nodes(index,:);

end

function [truth,type] = checkplaneAABBintersect(nodes,planepoint,planenormal,tol,varargin)
% PLANE AABB INTERSECTION CHECKER - Checks if a plane and an AABB
% intersect each other. The inputs are the nodes of the AABB (row
% containing xyz coordinates), a point on the plane (row vector with xyz
% coordinates) and a normal vector to the plane (row vector with xyz
% direction coefficients). The output is a simple true or false statement.
% If requested, the type of intersection can also be returned. The possible
% types are 'vertex', 'edge', 'face' and 'interior'.
%
% Reference: Essential Mathematics for Games & Interactive Applications: A 
% Programmer's Guide by Berth & Bishop

opt=struct('positiveforface',false);
opt=merge_options(opt,varargin{:});

% Find diagonal pairs and vectors in each diagonal
[nodepair,diagdir] = diagnodes(nodes,tol);

% Find diagonal vector closest to plane normal. This is done by projecting
% the plane normal vector on each diagonal and checking which projection
% length is the longest. The longest projection length corresponds to the
% diagonal direction that is the closest to the plane normal.
projectionlength=abs(dot(repmat(planenormal,4,1),diagdir,2));
[~,index]=max(projectionlength); % find index of largest projection length
nodepair=nodepair(index,:); % use index to find/save closest diagonal pair

% Check if the diagonal intersects the plane
endpoints=nodes(nodepair,:);
[diagintersect,~,diagtype] = linesegmentplaneintersect(endpoints,planepoint,planenormal,tol);

% if diagonal does not intersect the plane, plane does not intersect
% AABB, function terminates here
% if diagonal intersects the plane and the type is 'interior', function
% also terminates here
if ~diagintersect
    truth=false;
    type='none';
    return;
elseif strcmp(diagtype,'interior')
    truth=true;
    type=diagtype;
    return;
else
    truth=true;
end

function truth=circularfilter(mcellnodes,planenormal,planepoints,tol,varargin)

opt=struct('gaugetol',0,'gaugeradius',0,'center',[],'mcellcentroid',[]);
opt=merge_options(opt,varargin{:});

if isempty(opt.center)
    center=sum(planepoints)/size(planepoints,1);
else
    center=opt.center;
end

if abs(opt.gaugetol)<tol
    gaugetol=norm(max(mcellnodes)-min(mcellnodes));
else
    gaugetol=opt.gaugetol; 
end

if abs(opt.gaugeradius)<tol
    temp=planepoints-repmat(center,size(planepoints,1),1);
    temp=(temp(:,1).^2) + (temp(:,2).^2) +(temp(:,3).^2);
    gaugeradius=realsqrt(max(temp));
else
    gaugeradius=opt.gaugeradius; 
end

if isempty(opt.mcellcentroid)
    mcellcentroid=sum(mcellnodes)/size(mcellnodes,1);
else
    mcellcentroid=opt.mcellcentroid;
end

forbidrad=gaugeradius+gaugetol;

% calculate cell centroid to plane centroid distance along plane.
planenormal=planenormal/norm(planenormal);
relpos=mcellcentroid-center;
normdist=abs(dot(relpos,planenormal));
actdist=norm(relpos);
pardist=realsqrt((actdist^2)-(normdist^2));

if (pardist-forbidrad)>tol % if centroid to center distance is larger than forbidden radius, then no intersection
    truth=false;
else
    truth=true;
end

