function edges=findAABBedges(AABBnodes,tol)
% FIND AABB EDGES. Takes in the nodal positions of an AABB (each row
% containing xyz coordinates). The output is a 12x2 matrix with each row
% containing the row indices of vertices that form an edge.

% METHODOLOGY: We make use of the fact that an AABB is axis-aligned. So for
% every vertex pair that forms an edge, only one of the coordinates can be
% different. We start with vertex1, compare with vertices 2 through 8. Then
% move on to vertex2, compare with vertices 3 through 8. This continues
% until vertex7, which is compared with vertex8.

edges=zeros(12,2); % initialize edges
count=1;
for i=1:7
    xi=AABBnodes(i,1); yi=AABBnodes(i,2); zi=AABBnodes(i,3);
    for j=(i+1):8
        xj=AABBnodes(j,1); yj=AABBnodes(j,2); zj=AABBnodes(j,3);
        xsame=(abs(xi-xj)<tol);
        ysame=(abs(yi-yj)<tol);
        zsame=(abs(zi-zj)<tol);
        if (~xsame && ysame && zsame) || (xsame && ~ysame && zsame) || (xsame && ysame && ~zsame)
            edges(count,:)=[i,j];   
            count=count+1;
        end
    end
end


end

function faces=findAABBfaces(AABBnodes,tol)
% FIND AABB FACES. Takes in the nodal positions of an AABB (each row
% containing xyz coordinates). The output is a 6x4 matrix with each row
% containing the row indices of vertices that form a face.

% METHODOLOGY: We make use of the fact that an AABB is axis-aligned. We
% first extract the max/min x,y,z coordinates. Then for each one of them,
% we find the four vertices containing them.

xcoords=AABBnodes(:,1);
ycoords=AABBnodes(:,2);
zcoords=AABBnodes(:,3);
xmin=min(xcoords);
xmax=max(xcoords);
ymin=min(ycoords);
ymax=max(ycoords);
zmin=min(zcoords);
zmax=max(zcoords);

faces=zeros(6,4); % initialize faces

% left face (xmin)
onface=(abs(xcoords-xmin*ones(8,1))<tol);
index=find(onface);
faces(1,:)=index';

% right face (xmax)
onface=(abs(xcoords-xmax*ones(8,1))<tol);
index=find(onface);
faces(2,:)=index';

% front face(ymin)
onface=(abs(ycoords-ymin*ones(8,1))<tol);
index=find(onface);
faces(3,:)=index';

% back face(ymax)
onface=(abs(ycoords-ymax*ones(8,1))<tol);
index=find(onface);
faces(4,:)=index';

% top face(zmin)
onface=(abs(zcoords-zmin*ones(8,1))<tol);
