end


end

function squarepoints=quad2square3D(quadpoints,tol,varargin)
% This function takes the vertices of a 3D quadrilateral and performs a
% perspective projection onto a square on the x-y plane. Area is preserved
% unless specified.
%
% Refer to https://www.geometrictools.com/Documentation/PerspectiveMappings.pdf

opt=struct('unitarea',false);
opt=merge_options(opt,varargin{:});

squarepoints=zeros(4,3);

[maxdiag,mindiag,~,~]=findquaddiag3D(quadpoints);

vertA=maxdiag(1); vertB=mindiag(1); vertC=maxdiag(2); vertD=mindiag(2);

if opt.unitarea
    edgelength=1;
else
    area=convexpolygonarea(quadpoints([vertA,vertB,vertC,vertD],:),tol);
    edgelength=realsqrt(area);
end

W=quadpoints(vertC,:)-quadpoints(vertA,:);
U=quadpoints(vertB,:)-quadpoints(vertA,:);
V=quadpoints(vertD,:)-quadpoints(vertA,:);

UdotU=dot(U,U); VdotV=dot(V,V); UdotV=dot(U,V);
UdotW=dot(U,W); VdotW=dot(V,W);

A=[UdotU,UdotV;UdotV,VdotV]; b=[UdotW;VdotW];

sol=A\b;

a0=sol(1); a1=sol(2);

%% vertA transformation
y0=0; y1=0;
[x0,x1]=transform(y0,y1,a0,a1,edgelength);
squarepoints(vertA,1:2)=[x0,x1];

%% vertB transformation
y0=1; y1=0;
[x0,x1]=transform(y0,y1,a0,a1,edgelength);
squarepoints(vertB,1:2)=[x0,x1];

function quadpoints=square2quad3D(squarepoints,quadverts,tol,varargin)
% This function takes squarepoints, quadverts and transforms the square
% points into points in the quadrilateral defined by quadverts.

opt=struct('area',-1);
opt=merge_options(opt,varargin{:});

[maxdiag,mindiag,~,~]=findquaddiag3D(quadverts);

vertA=maxdiag(1); vertB=mindiag(1); vertC=maxdiag(2); vertD=mindiag(2);

%% scale square points to unit square
if opt.area<0
    area=convexpolygonarea(quadverts([vertA,vertB,vertC,vertD],:),tol);
    edgelength=realsqrt(area);
else
    edgelength=realsqrt(opt.area);
end

squarepoints=squarepoints./edgelength; %scaled to unit square

%% Get back quadrilateral points
W=quadverts(vertC,:)-quadverts(vertA,:);
U=quadverts(vertB,:)-quadverts(vertA,:);
V=quadverts(vertD,:)-quadverts(vertA,:);

UdotU=dot(U,U); VdotV=dot(V,V); UdotV=dot(U,V);
UdotW=dot(U,W); VdotW=dot(V,W);

A=[UdotU,UdotV;UdotV,VdotV]; b=[UdotW;VdotW];

sol=A\b;

a0=sol(1);
a1=sol(2);

numpoints=size(squarepoints,1);
quadpoints=zeros(numpoints,3);
for i=1:numpoints
    x0=squarepoints(i,1);
    x1=squarepoints(i,2);
    [y0,y1]=transform(x0,x1,a0,a1);
    quadpoints(i,:)=quadverts(vertA,:)+(y0*U)+(y1*V);   
end

