function fracplanes=circDFNfracplanesgenerator(numpoints,celldim,setdensity,setnormal,setnormalK, ...
    setradius,setradiusvar,shadowmult,tol)
% fracplane generator for EDFM. Function expands boundary by 30% in all
% directions and creates a larger space for DFN generation. Then circles
% are generated based on input parameters. Discrete points are generated to
% represent the circles, then clipped against the original domain
% dimensions. The output is a struct fracplanes which contains the field
% points. The field points will contain the vertices of a fracture plane in
% a sequential manner.

expdomain=celldim*1.6; % expanded domain
shift=celldim*0.3; % translation vector

% clipping plane and direction to keep
planepointleft=[0 0 0]+shift; planedirectionleft=[1 0 0];
planepointright=celldim+shift; planedirectionright=[-1 0 0];
planepointtop=[0 0 0]+shift; planedirectiontop=[0 0 1];
planepointbottom=celldim+shift; planedirectionbottom=[0 0 -1];
planepointfront=[0 0 0]+shift; planedirectionfront=[0 1 0];
planepointback=celldim+shift; planedirectionback=[0 -1 0];

circledfn=circleDFNgenerator(expdomain,setdensity,setnormal,setnormalK, ...
    setradius,setradiusvar,shadowmult,tol);

fracplanes=struct('points',[]);
count=0;
for i=1:length(circledfn)
    % generate polygon for each circle
    points=circlepoints(numpoints,circledfn(i).center,circledfn(i).normal,circledfn(i).radius,'randomize',true);

    % clip against each plane
    points=polygonplaneclip(points,planepointleft,planedirectionleft,tol);
    if size(points,1)==0,continue; end;
    points=polygonplaneclip(points,planepointright,planedirectionright,tol);
    if size(points,1)==0,continue; end;
    points=polygonplaneclip(points,planepointtop,planedirectiontop,tol);
    if size(points,1)==0,continue; end;
    points=polygonplaneclip(points,planepointbottom,planedirectionbottom,tol);
    if size(points,1)==0,continue; end;
    points=polygonplaneclip(points,planepointfront,planedirectionfront,tol);
    if size(points,1)==0,continue; end;
    points=polygonplaneclip(points,planepointback,planedirectionback,tol);
    if size(points,1)==0,continue; end;
    % if we pass through all clipping steps above and did not go to next
    % loop, then we clipped a polygon

function circledfn=circleDFNgenerator(celldim,density,normal,normalK,radius,radiusvar,shadowmult,tol)
% DFN generator for one set of circular fractures. 
% This function takes in celldim which is the rectangular domain
% dimensions [xlength, ylength, zlength]. Density is the
% P31 density of the fracture set. normal is the direction of the mean
% normal direction. normalvar the variation of the normal direction.
% radius is the mean radius. radius var is the variation of the radius.
%
% circledfn (output) is a structure containing data on the radius, normal
% direction and center location of each fracture within celldim.
%
% Method used here is from Discontinuity Analysis for Rock Engineering by
% Priest (1993). Section 6.8.

% AS A START, THIS FUNCTION DOES NOT INCLUDE VARIATION IN NORMAL DIRECTION
% AND CIRCLE RADIUS.

cellvol=celldim(1)*celldim(2)*celldim(3);

targetnum=round(density*cellvol); % round to the nearest integer
fraccount=0;
circledfn=struct('center',[0 0 0],'normal',[0 0 0],'radius',0);
newcircle=struct('center',[0 0 0],'normal',[0 0 0],'radius',0);
intersectnum=0;
while fraccount<targetnum % stops when fraccount=targetnum
    [newcircle.center,newcircle.normal,newcircle.radius]=generateonecircle(celldim,normal,normalK,radius,radiusvar);

    % check for circle-shadowzone intersect with all previous circles
    for i=1:fraccount
        intersect=circleshadowintersect(newcircle,circledfn(i),shadowmult,tol);
        if (intersect), intersectnum=intersectnum+1; break; end
    end
    if (fraccount>0) && intersect, continue; end;

    % quick hack to add angle variation
    newcircle.normal=randdirection(normal,normalK,tol);


    fraccount=fraccount+1;
    circledfn(fraccount)=newcircle;
end

printout=['DFN completed with ',num2str(intersectnum),' fracture(s) discarded due to intersection with shadow zone.'];
disp(printout);

function truth=circleshadowintersect(newcircle,oldcircle,shadowmult,tol)
% Checks whether new circle invades shadow zone of old circle. We assume
% that both circles are parallel. The shadowzone will be a cylinder around
% the old circle. The cylinder will have height of shadowmult*diameter and
% radius of (1+shadowmult)*radius.

h=oldcircle.radius*shadowmult;
r=oldcircle.radius*(1+shadowmult);

% First check that the normal distance between the circles exceeds 'h'. If
% this is exceeded, the new circle definitely does not enter the shadowzone
% of the old circle.
centnew=newcircle.center;
centold=oldcircle.center;
normalnew=newcircle.normal; normalnew=normalnew/norm(normalnew);
normalold=oldcircle.normal; normalold=normalold/norm(normalold);
normalave=0.5*(normalnew+normalold);
normaldist=abs(dot(centnew-centold,normalave));
if (normaldist-h)>tol
    truth=false; return;
end

% if normal distance is within h, then we check the center to center
% distance between the two circles. We project this distance onto a
% direction parallel to the circles and compare this to the sum of the new
% circle's radius and the shadowzone radius.
centdist=norm(centnew-centold);
projcentdist=sqrt((centdist^2)-(normaldist^2));

sumrad=newcircle.radius+r;

if (projcentdist-sumrad)>tol % if the projected distance is longer than the sum of radii, then the new circle does not intersect shadowzone
    truth=false; return;
else
    truth=true;return;
end





end

function fracture=createexclusionzone(fracture,allowance,varargin)
% given points that describe a convex polygon, this function defines an
% exclusion zone using the allowance. The exclusion zone is an extruded
% expanded polygon. The polygon vertices are moved further away by
% allowance*distance and the thickness of the exclusion zone is
% allowance*meandistance well.
%
% the output will be a struct class object containing the fields surfaces.
% Each field will contain information on the vertices of the surfaces and
% the normal direction of the surfaces pointing into the exclusion zone.
% The surfaces together form the exclusion zone.
%
% An option is provided to triangulate all surfaces for later intersection
% checking. Triangulation will create a triangle list for every surface.
% Each row in this triangle list will contain indices of nodes that form a
% triangle.

opt=struct('triangulate',true,'visualize',false,'arranged',true);
opt=merge_options(opt,varargin{:});

%% Create exclusion zone
fsize=fracture.size;
points=fracture.points;
numpoints=size(points,1);

planenormal=fracture.normal;

if ~opt.arranged
    points=arrangenodes(points,planenormal);
end

centroid=sum(points)/numpoints;

tempdirs=points-repmat(centroid,numpoints,1);
tempdirslength=realsqrt((tempdirs(:,1).^2)+(tempdirs(:,2).^2)+(tempdirs(:,3).^2));
tempdirs=tempdirs./repmat(tempdirslength,1,3);
extendpoints=points+allowance*fsize*tempdirs;

% surface 1 calculation: one side of the polygon
% meandist=points-repmat(centroid,numpoints,1);
% meandist=realsqrt((meandist(:,1).^2)+(meandist(:,2).^2)+(meandist(:,3).^2));
% meandist=sum(meandist)/numpoints;
exclusionzone.surface1.points=extendpoints+0.5*allowance*fsize*repmat(planenormal,numpoints,1);
exclusionzone.surface1.insidedirection=-planenormal;

