function direction=directionvector(azimuth,elevation,varargin)
% generates a direction vector from azimuth and elevation. pn/pv pair
% available to specify 'units' in 'degrees' or to change the reference
% direction 'refdir' to any other direction.
opt=struct('units','radians','refdir',[0 0 1]);
opt=merge_options(opt,varargin{:});

if strcmp(opt.units,'degrees')
    azimuth=azimuth*pi/180;
    elevation=elevation*pi/180;
end

direction=(opt.refdir)'; % make column vector for computation purposes
direction=rotaroundy(elevation)*direction;
direction=rotaroundz(azimuth)*direction;
direction=direction'; % make row vector per convention
end

function rotmat=rotaroundy(angle)
rotmat=[cos(angle) 0 sin(angle);
        0 1 0;
        (-sin(angle)) 0 cos(angle)];
end

function rotmat=rotaroundz(angle)
rotmat=[cos(angle) (-sin(angle)) 0;
        sin(angle) cos(angle) 0;
        0 0 1];
end

function [azimuth,elevation]=findaziele(direction,tol,varargin)

opt=struct('unit','radians');
opt=merge_options(opt,varargin{:});


% convert direction to column vector if it is a row
if size(direction,1)==1
    direction=direction';
end
assert(size(direction,1)==3);
assert(size(direction,2)==1);

% determine quadrant in x-y plane
xdir=[1;0;0];
ydir=[0;1;0];
zdir=[0;0;1];
xcoord=dot(direction,xdir);
ycoord=dot(direction,ydir);

azimuth=atan(ycoord/xcoord);

% correct for quadrant
quadrant=-1;
if xcoord<=tol && ycoord<=tol
    quadrant=0;
    azimuth=0; % prevent NaN output. In this case, elevation will be 0 or pi
elseif xcoord>=0 && ycoord>=0
    quadrant=1;
elseif xcoord<=0 && ycoord>=0
    quadrant=2;
    azimuth=pi+azimuth;
elseif xcoord<=0 && ycoord<=0
    quadrant=3;
    azimuth=pi+azimuth;
elseif xcoord>=0 && ycoord<=0
    quadrant=4;
    azimuth=2*pi+azimuth;
end

assert(quadrant>=0);


length=norm(direction);

function angle=fisherrandom(K,varargin)
% generates a random number between 0 and pi/2 based on fisher
% distribution. pn/pv pair can be input to change output to an angle in
% degrees instead of the default in radians. 'unit'/'degrees'/'radians'

opt=struct('unit','radians');
opt=merge_options(opt,varargin{:});

angle=acos(1+log(1-rand)/K);

if strcmp(opt.unit,'degrees')
    angle=angle*180/pi;
end


end

function truth=intersectexclusionzone(newfracture,oldfracture,tol)
% This function takes in the new and old fractures and check if the new
% fracture intrudes the exclusion zone of the old fracture. The output is a
% simple true/false statement.
%
% This function uses repeated triangle-triangle intersection checks to see
% if the new fracture intersects the old fracture's exclusion zone.

%% Quick filter by sphere
% Both fractures will be made into spheres. If the spheres do not collide,
% the fractures do not intersect.

newcenter=mean(newfracture.points,1);
pointrelpos=bsxfun(@minus,newfracture.points,newcenter);
newrad=realsqrt(max(sum(pointrelpos.^2,2)));

oldcenter=mean(oldfracture.points,1);
pointrelpos=bsxfun(@minus,oldfracture.exclusionzone.surface1.points,oldcenter);
oldrad=realsqrt(max(sum(pointrelpos.^2,2)));

centerdist=norm(newcenter-oldcenter);

% if the distance between centers is larger than the sum of radii, then the
% two spheres don't intersect, hence the two fractures don't intersect.
if centerdist > (newrad + oldrad)
    truth=false;
    return;
end



%% Check if any vertex of new fracture is within exclusion zone
numexzonesurf=length(fieldnames(oldfracture.exclusionzone)); % number of exclusion zone surfaces
newverts=newfracture.points;
numnewverts=size(newverts,1);
flag=zeros(numnewverts,1);
for i=1:numexzonesurf
    fieldname=['surface',num2str(i)];
    refpoint=oldfracture.exclusionzone.(fieldname).points(1,:);
    insidedir=oldfracture.exclusionzone.(fieldname).insidedirection;

    normdist=dot(newverts-repmat(refpoint,numnewverts,1),repmat(insidedir,numnewverts,1),2);
    normdist(normdist>0)=1;
    normdist(normdist<0)=-1;
    normdist(normdist==0)=0;

function [truth,point,type] = linesegmentplaneintersect(endpoints,planepoint,planenormal,tol)
% LINE SEGMENT VS PLANE INTERSECTION - Inputs are endpoints (2 rows
% each containing xyz coordinates of line endpoints), planepoint (row
% vector containing xyz coordinates of a point on plane) and planenormal
% (row vector containing xyz coefficient of normal vector). Returns a true
% or false statement. Also returns type of intersection: which can be
% 'none', 'interior', 'line', 'endpoint'. Lastly, returns the intersection
% point(s)(xyz coordinate row vector or [])

% Methodology: Determine the sides that the endpoints are on (relative to
% the plane point and plane normal). If one or both endpoints are on the
% plane, truth is true and type is 'endpoint'. If both signs are the same,
% truth is false and type is 'none'. If both signs are different, then truth
% is true and type is 'interior'.

% sign calculation
relposition=endpoints-repmat(planepoint,2,1);
sign=dot(relposition,repmat(planenormal,2,1),2);
sign(abs(sign)>0)=sign(abs(sign)>0)./abs(sign(abs(sign)>0));

% determine truth and type
if any(abs(sign)<tol)
    truth=true; point=endpoints(abs(sign)<tol,:); 
    if size(point,1)==1
        type='endpoint';
    else
        type='line';
    end
    return;
elseif abs(sum(sign))<tol
    truth=true; type='interior';
else
    truth=false; type='none'; point=[]; return;
end

% if successfully exit if-elseif-else block, find the intersection point
r=dot(planenormal,planepoint-endpoints(1,:))/dot(planenormal,endpoints(2,:)-endpoints(1,:));
point=endpoints(1,:)+r*(endpoints(2,:)-endpoints(1,:));

end

