    for np = 1:numel(WP.prod)
        WP.prod(np).alloc  = z*WP.prod(np).alloc  + w*diagn{k}.WP.prod(np).alloc;
        WP.prod(np).ralloc = z*WP.prod(np).ralloc + w*diagn{k}.WP.prod(np).ralloc;

